# 内置的全部项目文件(由「复制代码」页面自动生成,与 GitHub 仓库内容一致)
FILES = json.loads(r'''{"server/workers.py":"\"\"\"GPU 工作进程。每个进程独占一张卡(CUDA_VISIBLE_DEVICES),互不抢 GIL,从而真正实现双卡并行。\n\n进程划分 (Kaggle T4 x2) —— 全部常驻显存,服务不退出就不会卸载:\n  GPU0: tts0 (Qwen3-TTS-1.7B, CUDA Graph 流式)  +  llm (Qwen3-4B-Instruct-2507, 长输出)\n  GPU1: tts1 (Qwen3-TTS-1.7B, CUDA Graph 流式)  +  aux (Whisper ASR + WavLM 说话人相似度)\n\n协议: inq 收到 {\"id\",\"op\",\"args\"};outq 回复 {\"id\",\"type\": delta|final|error, \"data\"}。\n  - chat : delta 为文本片段\n  - synth: delta 为 {\"pcm\": float32 ndarray, \"sr\": int} 音频块(流式)\n\"\"\"\nimport os\nimport sys\nimport threading\nimport time\nimport traceback\n\nimport numpy as np\n\nfrom . import config\n\n\n# ----------------------------------------------------------------------------\n# Mock 实现 (CLONE_MOCK=1) —— 不依赖 torch,用于验证整条链路\n# ----------------------------------------------------------------------------\ndef _fake_voice(text: str, sr: int, seed: int = 0) -> np.ndarray:\n    dur = min(12.0, 0.35 + 0.17 * len(text))\n    t = np.arange(int(sr * dur)) / sr\n    f0 = 140 + 25 * np.sin(2 * np.pi * 0.7 * t + seed)\n    phase = 2 * np.pi * np.cumsum(f0) / sr\n    sig = sum(np.sin(k * phase) / k for k in range(1, 6))\n    env = 0.5 * (1 + np.sin(2 * np.pi * 3.2 * t)) ** 0.7\n    x = 0.25 * sig * env\n    return x.astype(np.float32)\n\n\nclass MockTTS:\n    def __init__(self, gpu):\n        self.gpu, self.voices = gpu, {}\n\n    def load(self, args, emit):\n        time.sleep(0.4)\n        return {\"device\": \"mock:%d\" % self.gpu, \"engine\": \"mock-stream\"}\n\n    def prepare(self, args, emit):\n        time.sleep(0.3)\n        self.voices[args[\"voice_id\"]] = True\n        modes = [\"icl\", \"xvec\"] if (args.get(\"ref_text\") or \"\").strip() else [\"xvec\"]\n        return {\"modes\": modes}\n\n    def synth(self, args, emit, cancelled=lambda: False):\n        text = args[\"text\"]\n        seed = 0 if args.get(\"mode\") == \"icl\" else 1\n        wav = _fake_voice(text, config.SR, seed)\n        step = int(config.SR * 0.33)\n        time.sleep(0.12)\n        total = 0\n        for i in range(0, len(wav), step):\n            if cancelled():\n                break\n            time.sleep(0.05)  # 模拟 RTF≈6\n            emit({\"pcm\": wav[i : i + step], \"sr\": config.SR})\n            total += min(step, len(wav) - i)\n        return {\"samples\": total, \"sr\": config.SR}\n\n\nclass MockLLM:\n    def load(self, args, emit):\n        time.sleep(0.3)\n        return {\"device\": \"mock\"}\n\n    def chat(self, args, emit, cancelled):\n        last = args[\"messages\"][-1][\"content\"]\n        reply = (\n            \"好的,我听到了你说的:%s。这是一段用来测试的模拟回答,它会被切成很多短句。\"\n            \"第一句很短,所以首声会很快出现。后面的句子会稍微长一点,双卡会交替合成,\"\n            \"播放的时候不应该出现任何停顿。我们再多说几句,用来验证长文本输出能力,\"\n            \"看看流式分句、乱序到达和顺序播放是不是都正常。最后,祝你使用愉快。\" % last[:30]\n        )\n        if \"__LLM_FAIL__\" in last:\n            raise RuntimeError(\"模拟的 LLM 故障(用于验证错误必定回显,不会静默卡死)\")\n        for i in range(0, len(reply), 2):\n            if cancelled():\n                break\n            time.sleep(0.03)\n            emit(reply[i : i + 2])\n        return {\"text\": reply}\n\n\nclass MockAux:\n    def load(self, args, emit):\n        time.sleep(0.2)\n        return {\"device\": \"mock\", \"asr\": True, \"sv\": True}\n\n    def asr(self, args, emit):\n        return {\"text\": \"这是模拟的语音识别结果\", \"language\": \"zh\"}\n\n    def sim(self, args, emit):\n        a, b = args[\"a\"], args[\"b\"]\n        return {\"cosine\": 0.93 if len(a) and len(b) else 0.0}\n\n\n# ----------------------------------------------------------------------------\n# 真实实现  (每个进程只看得到一张卡 → 一律使用 cuda:0)\n# ----------------------------------------------------------------------------\ndef _from_pretrained(cls, name, dtype, **kw):\n    \"\"\"兼容 transformers 4.x(torch_dtype) 与 5.x(dtype)。\"\"\"\n    try:\n        return cls.from_pretrained(name, dtype=dtype, **kw)\n    except TypeError:\n        return cls.from_pretrained(name, torch_dtype=dtype, **kw)\n\n\nclass RealTTS:\n    def __init__(self, gpu):\n        self.gpu, self.model, self.fast = gpu, None, None\n        self.dtype_name = config.TTS_DTYPE\n        self.preps: dict[str, dict] = {}\n        self.engine_name = \"?\"\n\n    # ---- 加载 ----\n    def _load_model(self, dtype_name):\n        import torch\n\n        dt = getattr(torch, dtype_name)\n        self.fast = None\n        try:\n            from faster_qwen3_tts import FasterQwen3TTS\n\n            self.fast = FasterQwen3TTS.from_pretrained(\n                config.TTS_MODEL, device=\"cuda\", dtype=dt, attn_implementation=\"sdpa\", max_seq_len=1536\n            )\n            self.model = self.fast.model\n            self.engine_name = \"faster-qwen3-tts(CUDA Graph 流式)\"\n            try:\n                self.fast.warmup(prefill_len=120)\n            except Exception as e:  # noqa: BLE001\n                print(\"[tts gpu%d] CUDA Graph 预热失败(首次合成时再捕获): %s\" % (self.gpu, e), flush=True)\n        except Exception as e:  # noqa: BLE001\n            print(\"[tts gpu%d] faster-qwen3-tts 不可用,回退官方 qwen-tts(整句合成,较慢): %s\" % (self.gpu, e), flush=True)\n            self.fast = None\n            from qwen_tts import Qwen3TTSModel\n\n            self.model = _from_pretrained(Qwen3TTSModel, config.TTS_MODEL, dt, device_map=\"cuda\", attn_implementation=\"sdpa\")\n            self.engine_name = \"qwen-tts(官方,非流式)\"\n        self.dtype_name = dtype_name\n\n    def load(self, args, emit):\n        self._load_model(self.dtype_name)\n        return {\"device\": \"cuda(GPU%d)\" % self.gpu, \"dtype\": self.dtype_name, \"engine\": self.engine_name}\n\n    def _fallback_bf16(self):\n        \"\"\"fp16 数值溢出(输出 NaN/全零)时,换 bf16 重新加载并重建所有声音。\"\"\"\n        import gc\n\n        import torch\n\n        self.model = self.fast = None\n        self.preps_keep = dict(self.preps)\n        self.preps = {}\n        gc.collect()\n        torch.cuda.empty_cache()\n        self._load_model(\"bfloat16\")\n        for a in list(self.preps_keep.values()):\n            self.prepare(a, None)\n\n    # ---- 声音 prompt ----\n    def prepare(self, args, emit):\n        \"\"\"构建/预热可复用的声音克隆 prompt(ICL 与 x-vector 两种都构建,后续择优)。\"\"\"\n        vid, path, text = args[\"voice_id\"], args[\"ref_path\"], (args.get(\"ref_text\") or \"\").strip()\n        self.preps[vid] = args\n        modes = []\n        if text:\n            modes.append(\"icl\")\n        modes.append(\"xvec\")\n        lang = \"Chinese\" if any(\"\\u4e00\" <= c <= \"\\u9fff\" for c in text) or not text else \"English\"\n        for m in modes:  # 真实合成一小句 → 缓存声纹 + 让 CUDA Graph 完全热起来\n            for _ in self._gen(vid, \"嗯。\" if lang == \"Chinese\" else \"Hmm.\", lang, m, chunk=8):\n                pass\n        return {\"modes\": modes}\n\n    # ---- 合成 ----\n    def _gen(self, vid, text, lang, mode, chunk, cancelled=lambda: False):\n        a = self.preps[vid]\n        ref, ref_text = a[\"ref_path\"], (a.get(\"ref_text\") or \"\").strip()\n        if mode == \"icl\" and not ref_text:\n            mode = \"xvec\"\n        max_new = int(min(1200, max(72, len(text) * 6 + 48)))\n        kw = dict(temperature=0.8, top_k=40, top_p=0.95, repetition_penalty=1.05)\n        if self.fast is not None:\n            for audio, sr, _timing in self.fast.generate_voice_clone_streaming(\n                text=text, language=lang, ref_audio=ref, ref_text=ref_text,\n                xvec_only=(mode == \"xvec\"), chunk_size=chunk, max_new_tokens=max_new, **kw,\n            ):\n                if cancelled():\n                    return\n                yield np.asarray(audio, dtype=np.float32).reshape(-1), int(sr)\n        else:\n            key = (vid, mode)\n            cache = self.__dict__.setdefault(\"_prompt_cache\", {})\n            if key not in cache:\n                cache[key] = (\n                    self.model.create_voice_clone_prompt(ref_audio=ref, ref_text=ref_text, x_vector_only_mode=False)\n                    if mode == \"icl\"\n                    else self.model.create_voice_clone_prompt(ref_audio=ref, ref_text=None, x_vector_only_mode=True)\n                )\n            wavs, sr = self.model.generate_voice_clone(\n                text=text, language=lang, voice_clone_prompt=cache[key], max_new_tokens=max_new\n            )\n            w = wavs[0]\n            if hasattr(w, \"detach\"):\n                w = w.detach().float().cpu().numpy()\n            yield np.asarray(w, dtype=np.float32).reshape(-1), int(sr)\n\n    def synth(self, args, emit, cancelled=lambda: False):\n        text, vid = args[\"text\"], args[\"voice_id\"]\n        lang, mode = args.get(\"lang\", \"Chinese\"), args.get(\"mode\", \"icl\")\n        chunk = int(args.get(\"chunk\", config.TTS_CHUNK_NEXT))\n        for attempt in (0, 1):\n            total, sr_out, bad = 0, config.SR, False\n            for w, sr in self._gen(vid, text, lang, mode, chunk, cancelled):\n                if not np.all(np.isfinite(w)):\n                    bad = True\n                    break\n                if total == 0 and w.size and float(np.max(np.abs(w))) < 1e-5 and w.size > sr * 0.2:\n                    bad = True\n                    break\n                total += w.size\n                sr_out = sr\n                emit({\"pcm\": w, \"sr\": sr})\n            if not bad:\n                return {\"samples\": total, \"sr\": sr_out}\n            if attempt == 1 or self.dtype_name != \"float16\":\n                raise RuntimeError(\"TTS 输出异常(NaN/静音),请把环境变量 TTS_DTYPE 设为 bfloat16 再试\")\n            print(\"[tts gpu%d] fp16 输出异常,自动回退 bfloat16\" % self.gpu, flush=True)\n            self._fallback_bf16()\n        raise RuntimeError(\"unreachable\")\n\n\nclass RealLLM:\n    def __init__(self, gpu):\n        self.gpu, self.model, self.tok = gpu, None, None\n        self.dtype_name = config.LLM_DTYPE\n\n    def load(self, args, emit):\n        import torch\n        from transformers import AutoModelForCausalLM, AutoTokenizer\n\n        self.tok = AutoTokenizer.from_pretrained(config.LLM_MODEL)\n        self.model = _from_pretrained(AutoModelForCausalLM, config.LLM_MODEL, getattr(torch, self.dtype_name))\n        self.model = self.model.to(\"cuda\").eval()\n        self.dev = \"cuda\"\n        self._warm()\n        return {\"device\": \"cuda(GPU%d)\" % self.gpu, \"dtype\": self.dtype_name}\n\n    def _warm(self):\n        import torch\n\n        ids = self.tok([\"你好\"], return_tensors=\"pt\").to(self.dev)\n        with torch.inference_mode():\n            out = self.model.generate(**ids, max_new_tokens=6, do_sample=False)\n        txt = self.tok.decode(out[0], skip_special_tokens=True)\n        if self.dtype_name == \"float16\" and (\"!!!!\" in txt or not txt.strip()):\n            print(\"[llm] fp16 预热输出异常(%r),自动换 bfloat16\" % txt, flush=True)\n            self._to_bf16()\n\n    def _to_bf16(self):\n        import torch\n\n        self.model = self.model.to(torch.bfloat16)\n        self.dtype_name = \"bfloat16\"\n\n    def _run_once(self, kw, streamer, cancelled, emit):\n        import queue\n\n        err = {}\n\n        def run():\n            import torch\n\n            try:\n                with torch.inference_mode():\n                    self.model.generate(**kw)\n            except BaseException as e:  # noqa: BLE001  必须捕获,否则 streamer 永远等不到结束信号 → 界面「没反应」\n                err[\"e\"] = e\n                err[\"tb\"] = traceback.format_exc()\n                try:\n                    streamer.end()\n                except Exception:  # noqa: BLE001\n                    streamer.text_queue.put(streamer.stop_signal)\n\n        th = threading.Thread(target=run, daemon=True)\n        th.start()\n        pieces, head, held, released = [], \"\", [], False\n        try:\n            for piece in streamer:\n                if not piece:\n                    continue\n                pieces.append(piece)\n                if not released:\n                    # 前 4 个字先扣住:fp16 溢出时模型会吐 \"!!!!\",不能让它出现在界面/语音里\n                    head += piece\n                    held.append(piece)\n                    if len(head) < 4:\n                        continue\n                    if self.dtype_name == \"float16\" and head.startswith(\"!!!!\"):\n                        kw[\"stopping_criteria\"][0].force = True\n                        break\n                    released = True\n                    for h in held:\n                        emit(h)\n                    held = []\n                    continue\n                emit(piece)\n            if held and not (self.dtype_name == \"float16\" and head.startswith(\"!!!!\")):\n                for h in held:\n                    emit(h)\n        except queue.Empty:\n            kw[\"stopping_criteria\"][0].force = True\n            raise RuntimeError(\"LLM 超过 %d 秒没有输出(可能显存不足或模型卡死)\" % int(config.LLM_STALL_TIMEOUT))\n        th.join(timeout=5)\n        return pieces, err, head\n\n    def chat(self, args, emit, cancelled):\n        import torch\n        from transformers import StoppingCriteria, StoppingCriteriaList, TextIteratorStreamer\n\n        msgs = args[\"messages\"]\n        try:\n            prompt = self.tok.apply_chat_template(msgs, tokenize=False, add_generation_prompt=True, enable_thinking=False)\n        except TypeError:\n            prompt = self.tok.apply_chat_template(msgs, tokenize=False, add_generation_prompt=True)\n        inputs = self.tok([prompt], return_tensors=\"pt\").to(self.dev)\n\n        class Cancel(StoppingCriteria):\n            force = False\n\n            def __call__(self, input_ids, scores, **kw):\n                return torch.full((input_ids.shape[0],), bool(cancelled() or self.force), dtype=torch.bool, device=input_ids.device)\n\n        for attempt in (0, 1):\n            streamer = TextIteratorStreamer(\n                self.tok, skip_prompt=True, skip_special_tokens=True, timeout=config.LLM_FIRST_TOKEN_TIMEOUT\n            )\n            kw = dict(\n                **inputs,\n                streamer=streamer,\n                max_new_tokens=int(args.get(\"max_new_tokens\", config.LLM_DEFAULT_TOKENS)),\n                do_sample=True,\n                temperature=0.7,\n                top_p=0.8,\n                top_k=20,\n                repetition_penalty=1.05,\n                stopping_criteria=StoppingCriteriaList([Cancel()]),\n            )\n            pieces, err, head = self._run_once(kw, streamer, cancelled, emit)\n            garbage = self.dtype_name == \"float16\" and head.startswith(\"!!!!\")\n            if (err or garbage) and not pieces_ok(pieces, garbage) and attempt == 0 and self.dtype_name == \"float16\":\n                print(\"[llm] fp16 生成失败/输出异常,换 bfloat16 重试: %s\" % (err.get(\"tb\") or head), flush=True)\n                self._to_bf16()\n                continue\n            if err:\n                raise RuntimeError(\"LLM 生成失败: %s\" % (str(err[\"e\"]).strip().splitlines() or [repr(err[\"e\"])])[-1])\n            return {\"text\": \"\".join(pieces)}\n        raise RuntimeError(\"LLM 生成失败\")\n\n\ndef pieces_ok(pieces, garbage):\n    \"\"\"已经流出的正常文字不应因重试而重复:只有「还没输出任何有效内容」时才允许重试。\"\"\"\n    if garbage:\n        return False\n    return bool(\"\".join(pieces).strip())\n\n\nclass RealAux:\n    def __init__(self, gpu):\n        self.gpu = gpu\n        self.asr_pipe = self.sv = self.sv_fe = None\n        self.errors = {}\n\n    def load(self, args, emit):\n        import torch\n\n        self.dev = \"cuda\"\n        try:\n            from transformers import pipeline\n\n            try:\n                self.asr_pipe = pipeline(\"automatic-speech-recognition\", model=config.ASR_MODEL, dtype=torch.float16, device=self.dev)\n            except TypeError:\n                self.asr_pipe = pipeline(\"automatic-speech-recognition\", model=config.ASR_MODEL, torch_dtype=torch.float16, device=self.dev)\n        except Exception as e:  # noqa: BLE001\n            self.errors[\"asr\"] = repr(e)\n        try:\n            from transformers import AutoFeatureExtractor, WavLMForXVector\n\n            self.sv_fe = AutoFeatureExtractor.from_pretrained(config.SV_MODEL)\n            self.sv = WavLMForXVector.from_pretrained(config.SV_MODEL).to(self.dev).eval()\n        except Exception as e:  # noqa: BLE001\n            self.errors[\"sv\"] = repr(e)\n        return {\"device\": \"cuda(GPU%d)\" % self.gpu, \"asr\": self.asr_pipe is not None, \"sv\": self.sv is not None, \"errors\": self.errors}\n\n    def asr(self, args, emit):\n        if self.asr_pipe is None:\n            raise RuntimeError(\"ASR 未加载: %s\" % self.errors.get(\"asr\"))\n        x = np.asarray(args[\"samples\"], dtype=np.float32)  # 16k\n        out = self.asr_pipe({\"raw\": x, \"sampling_rate\": 16000}, chunk_length_s=30, return_timestamps=False)\n        return {\"text\": (out.get(\"text\") or \"\").strip()}\n\n    def _embed(self, x16):\n        import torch\n\n        inp = self.sv_fe(x16, sampling_rate=16000, return_tensors=\"pt\", padding=True)\n        inp = {k: v.to(self.dev) for k, v in inp.items()}\n        with torch.inference_mode():\n            e = self.sv(**inp).embeddings\n        e = torch.nn.functional.normalize(e.float(), dim=-1)\n        return e[0]\n\n    def sim(self, args, emit):\n        import torch\n\n        if self.sv is None:\n            raise RuntimeError(\"说话人模型未加载: %s\" % self.errors.get(\"sv\"))\n        ea = self._embed(np.asarray(args[\"a\"], dtype=np.float32))\n        eb = self._embed(np.asarray(args[\"b\"], dtype=np.float32))\n        return {\"cosine\": float(torch.dot(ea, eb).item())}\n\n\n# ----------------------------------------------------------------------------\n# 进程入口\n# ----------------------------------------------------------------------------\ndef _make(kind: str, gpu: int):\n    if config.MOCK:\n        return {\"tts\": lambda: MockTTS(gpu), \"llm\": MockLLM, \"aux\": MockAux}[kind]()\n    return {\"tts\": lambda: RealTTS(gpu), \"llm\": lambda: RealLLM(gpu), \"aux\": lambda: RealAux(gpu)}[kind]()\n\n\ndef worker_main(kind: str, gpu: int, inq, outq, cancel_val) -> None:\n    # 必须在 import torch 之前:让本进程只看到自己的那张卡 → 双卡真并行、互不干扰\n    if not config.MOCK:\n        os.environ[\"CUDA_VISIBLE_DEVICES\"] = str(gpu)\n    os.environ.setdefault(\"TOKENIZERS_PARALLELISM\", \"false\")\n    os.environ.setdefault(\"PYTORCH_CUDA_ALLOC_CONF\", \"expandable_segments:True\")\n    handler = None\n    while True:\n        msg = inq.get()\n        if msg is None:\n            break\n        rid, op, args = msg[\"id\"], msg[\"op\"], msg.get(\"args\", {})\n\n        def emit(piece, _rid=rid):\n            outq.put({\"id\": _rid, \"type\": \"delta\", \"data\": piece})\n\n        def cancelled(_rid=rid):\n            return cancel_val.value >= _rid\n\n        try:\n            t0 = time.time()\n            if handler is None:\n                handler = _make(kind, gpu)\n            if op in (\"chat\", \"synth\") and cancelled():\n                data = {\"cancelled\": True}\n            elif op == \"chat\":\n                data = handler.chat(args, emit, cancelled)\n            elif op == \"synth\":\n                data = handler.synth(args, emit, cancelled)\n            else:\n                data = getattr(handler, op)(args, emit)\n            if isinstance(data, dict):\n                data[\"_ms\"] = round((time.time() - t0) * 1000, 1)\n            outq.put({\"id\": rid, \"type\": \"final\", \"data\": data})\n        except Exception:  # noqa: BLE001\n            outq.put({\"id\": rid, \"type\": \"error\", \"error\": traceback.format_exc()})\n            if op == \"load\":\n                handler = None\n        sys.stdout.flush()\n","server/engine.py":"\"\"\"引擎:GPU 进程池 + 声音训练流水线 + 对话/语音流水线。\"\"\"\nimport asyncio\nimport json\nimport multiprocessing as mp\nimport queue as pyqueue\nimport shutil\nimport struct\nimport subprocess\nimport threading\nimport time\nimport uuid\n\nimport numpy as np\n\nfrom . import audio_utils as au\nfrom . import config\nfrom .text_chunker import SentenceChunker, clean_for_tts, detect_language, is_speakable\n\n\n# ----------------------------------------------------------------------------\n# 进程句柄\n# ----------------------------------------------------------------------------\nclass Worker:\n    def __init__(self, name: str, kind: str, gpu: int, loop: asyncio.AbstractEventLoop):\n        from .workers import worker_main\n\n        ctx = mp.get_context(\"spawn\")\n        self.name, self.kind, self.gpu, self.loop = name, kind, gpu, loop\n        self.inq, self.outq = ctx.Queue(), ctx.Queue()\n        self.cancel = ctx.Value(\"q\", 0)\n        self.proc = ctx.Process(target=worker_main, args=(kind, gpu, self.inq, self.outq, self.cancel), daemon=True)\n        self.pending: dict[int, asyncio.Queue] = {}\n        self.next_id = 1\n        self.inflight = 0\n        self.state = \"starting\"\n        self.error = None\n        self.info: dict = {}\n        self.busy_ms = 0.0\n\n    def start(self):\n        self.proc.start()\n        threading.Thread(target=self._reader, daemon=True, name=\"reader-\" + self.name).start()\n\n    def _reader(self):\n        while True:\n            try:\n                msg = self.outq.get(timeout=1.0)\n            except pyqueue.Empty:\n                if not self.proc.is_alive():\n                    break\n                continue\n            except (EOFError, OSError):\n                break\n            try:\n                self.loop.call_soon_threadsafe(self._dispatch, msg)\n            except RuntimeError:\n                break\n\n    def _dispatch(self, msg):\n        q = self.pending.get(msg[\"id\"])\n        if q is not None:\n            q.put_nowait(msg)\n\n    def submit(self, op: str, **args):\n        rid = self.next_id\n        self.next_id += 1\n        q: asyncio.Queue = asyncio.Queue()\n        self.pending[rid] = q\n        self.inflight += 1\n        self.inq.put({\"id\": rid, \"op\": op, \"args\": args})\n        return rid, q\n\n    def _done(self, rid):\n        self.pending.pop(rid, None)\n        self.inflight = max(0, self.inflight - 1)\n\n    async def call(self, op: str, **args):\n        rid, q = self.submit(op, **args)\n        try:\n            while True:\n                m = await q.get()\n                if m[\"type\"] == \"error\":\n                    raise RuntimeError(m[\"error\"])\n                if m[\"type\"] == \"final\":\n                    return m[\"data\"]\n        finally:\n            self._done(rid)\n\n    async def stream(self, rid, q):\n        try:\n            while True:\n                m = await q.get()\n                if m[\"type\"] == \"error\":\n                    raise RuntimeError(m[\"error\"])\n                if m[\"type\"] == \"delta\":\n                    yield m[\"data\"]\n                elif m[\"type\"] == \"final\":\n                    return\n        finally:\n            self._done(rid)\n\n    def stop(self):\n        try:\n            self.inq.put(None)\n            self.proc.join(timeout=2)\n            if self.proc.is_alive():\n                self.proc.terminate()\n        except Exception:  # noqa: BLE001\n            pass\n\n\ndef gpu_stats():\n    try:\n        out = subprocess.run(\n            [\"nvidia-smi\", \"--query-gpu=index,name,memory.used,memory.total,utilization.gpu\", \"--format=csv,noheader,nounits\"],\n            capture_output=True, text=True, timeout=5,\n        ).stdout.strip().splitlines()\n        res = []\n        for line in out:\n            p = [s.strip() for s in line.split(\",\")]\n            res.append({\"index\": int(p[0]), \"name\": p[1], \"mem_used\": int(p[2]), \"mem_total\": int(p[3]), \"util\": int(p[4])})\n        return res\n    except Exception:  # noqa: BLE001\n        return []\n\n\nclass Session:\n    def __init__(self):\n        self.history: list[dict] = []\n        self.task: asyncio.Task | None = None\n        self.turn = 0\n        self.llm_rid = 0\n\n    def trim(self):\n        total, keep = 0, []\n        for m in reversed(self.history):\n            total += len(m[\"content\"])\n            if total > config.HISTORY_CHARS:\n                break\n            keep.append(m)\n        self.history = list(reversed(keep))\n        while self.history and self.history[0][\"role\"] != \"user\":\n            self.history.pop(0)\n\n\n# ----------------------------------------------------------------------------\n# 引擎\n# ----------------------------------------------------------------------------\nclass Engine:\n    def __init__(self):\n        self.loop: asyncio.AbstractEventLoop | None = None\n        self.tts: list[Worker] = []\n        self.llm: Worker | None = None\n        self.aux: Worker | None = None\n        self.voice: dict | None = None\n        self.job: dict = {\"state\": \"idle\"}\n        self.gpu_count = 0\n        self.rng = np.random.default_rng()\n        self.turn_stats: dict = {}\n        self.fillers: list[dict] = []\n        self._last_filler = -1\n\n    # ---------- 启动 ----------\n    async def start(self):\n        self.loop = asyncio.get_running_loop()\n        n = 2 if config.MOCK else len(gpu_stats())\n        self.gpu_count = n\n        if n == 0:\n            raise RuntimeError(\"未检测到 GPU。请在 Kaggle 右侧 Settings → Accelerator 选择 GPU T4 x2。\")\n        tts_gpus = [0, 1] if n >= 2 else [0]\n        for i, g in enumerate(tts_gpus):\n            self.tts.append(Worker(\"tts%d\" % i, \"tts\", g, self.loop))\n        self.llm = Worker(\"llm\", \"llm\", 0, self.loop)\n        self.aux = Worker(\"aux\", \"aux\", 1 if n >= 2 else 0, self.loop)\n        for w in self.workers:\n            w.start()\n            asyncio.create_task(self._load(w))\n        asyncio.create_task(self._restore_voice())\n\n    @property\n    def workers(self):\n        return [*self.tts, *( [self.llm] if self.llm else [] ), *( [self.aux] if self.aux else [] )]\n\n    async def _load(self, w: Worker):\n        w.state = \"loading\"\n        t0 = time.time()\n        try:\n            w.info = await w.call(\"load\")\n            w.state = \"ready\"\n            w.info[\"load_s\"] = round(time.time() - t0, 1)\n        except Exception as e:  # noqa: BLE001\n            w.state = \"error\"\n            w.error = str(e)[-1500:]\n            print(\"[engine] worker %s 加载失败:\\n%s\" % (w.name, e), flush=True)\n\n    async def _wait_ready(self, ws, timeout=900):\n        t0 = time.time()\n        while any(w.state in (\"starting\", \"loading\") for w in ws):\n            if time.time() - t0 > timeout:\n                raise TimeoutError(\"模型加载超时\")\n            await asyncio.sleep(0.5)\n        bad = [w for w in ws if w.state != \"ready\"]\n        if bad:\n            raise RuntimeError(\"模型加载失败: \" + \", \".join(w.name for w in bad))\n\n    def ready_tts(self):\n        return [w for w in self.tts if w.state == \"ready\"]\n\n    def status(self):\n        return {\n            \"mock\": config.MOCK,\n            \"gpus\": gpu_stats(),\n            \"workers\": {\n                w.name: {\"gpu\": w.gpu, \"state\": w.state, \"inflight\": w.inflight, \"info\": w.info, \"error\": w.error}\n                for w in self.workers\n            },\n            \"voice\": self.voice_public(),\n            \"job\": self.job,\n            \"turn\": self.turn_stats,\n            \"fillers\": len(self.fillers),\n            \"models\": {\"tts\": config.TTS_MODEL, \"llm\": config.LLM_MODEL, \"asr\": config.ASR_MODEL},\n        }\n\n    def voice_public(self):\n        if not self.voice:\n            return None\n        return {k: v for k, v in self.voice.items() if k not in (\"ref_path\",)}\n\n    # ---------- 声音 ----------\n    async def _restore_voice(self):\n        meta = config.VOICE_DIR / \"current\" / \"meta.json\"\n        if not meta.exists():\n            return\n        try:\n            v = json.loads(meta.read_text(\"utf-8\"))\n            v[\"ref_path\"] = str(config.VOICE_DIR / \"current\" / v.get(\"ref_file\", \"ref.wav\"))\n            await self._wait_ready(self.ready_tts() or self.tts)\n            await asyncio.gather(*[\n                w.call(\"prepare\", voice_id=v[\"id\"], ref_path=v[\"ref_path\"], ref_text=v.get(\"ref_text\", \"\"))\n                for w in self.ready_tts()\n            ])\n            self.voice = v\n            await self._make_fillers()\n            print(\"[engine] 已恢复已训练的声音 %s\" % v[\"id\"], flush=True)\n        except Exception as e:  # noqa: BLE001\n            print(\"[engine] 恢复声音失败: %s\" % e, flush=True)\n\n    def _log(self, msg: str):\n        self.job.setdefault(\"log\", []).append(\"[%s] %s\" % (time.strftime(\"%H:%M:%S\"), msg))\n        self.job[\"log\"] = self.job[\"log\"][-40:]\n        print(\"[train] \" + msg, flush=True)\n\n    def _set(self, **kw):\n        self.job.update(kw)\n\n    async def start_training(self, audio: bytes, ref_text: str):\n        if self.job.get(\"state\") == \"running\":\n            raise RuntimeError(\"训练正在进行中\")\n        n = max(1, len(self.tts))\n        self.job = {\n            \"state\": \"running\", \"stage\": \"准备中\", \"progress\": 1, \"log\": [], \"warnings\": [],\n            \"gpus\": [{\"gpu\": w.gpu, \"progress\": 0, \"msg\": \"等待\"} for w in self.tts[:n]],\n            \"similarity\": None, \"quality\": None, \"started\": time.time(),\n        }\n        asyncio.create_task(self._train(audio, ref_text.strip()))\n\n    def _gpu_msg(self, i, progress, msg):\n        if i < len(self.job.get(\"gpus\", [])):\n            self.job[\"gpus\"][i].update(progress=progress, msg=msg)\n\n    async def _train(self, audio: bytes, ref_text: str):\n        try:\n            self._set(stage=\"等待模型加载\", progress=3)\n            await self._wait_ready([*self.tts, self.aux])\n            # 1. 参考音频清洗\n            self._set(stage=\"参考音频清洗(解码/降噪/切静音/归一化)\", progress=8)\n            x = await asyncio.to_thread(au.decode_audio, audio, config.SR)\n            if x.size < config.SR * 1.5:\n                raise ValueError(\"参考音频太短(<1.5s),请至少录制 5 秒以上\")\n            ref, quality, warns = await asyncio.to_thread(au.preprocess_reference, x, config.SR)\n            self._set(quality=quality, warnings=warns)\n            self._log(\"参考音频 %.1fs, 信噪比≈%.0fdB\" % (quality[\"duration\"], quality.get(\"snr_db_raw\", 0)))\n            vid = uuid.uuid4().hex[:8]\n            cur = config.VOICE_DIR / \"current\"\n            if cur.exists():\n                shutil.rmtree(cur, ignore_errors=True)\n            cur.mkdir(parents=True, exist_ok=True)\n            ref_path = cur / (\"ref_%s.wav\" % vid)  # 每次训练换新文件名,避免 TTS 内部按路径缓存到旧声音\n            await asyncio.to_thread(au.write_wav, ref_path, ref, config.SR)\n            # 2. 自动转写\n            if not ref_text:\n                self._set(stage=\"自动识别参考语音文本 (Whisper @ GPU%d)\" % self.aux.gpu, progress=18)\n                r = await self.aux.call(\"asr\", samples=au.resample(ref, config.SR, 16000))\n                ref_text = r[\"text\"]\n                self._log(\"识别文本: %s\" % ref_text)\n            # 3. 双卡同时构建声音 prompt\n            self._set(stage=\"双卡并行提取声纹/声学特征\", progress=30)\n            for i in range(len(self.tts)):\n                self._gpu_msg(i, 10, \"提取中\")\n\n            async def prep(i, w):\n                r = await w.call(\"prepare\", voice_id=vid, ref_path=str(ref_path), ref_text=ref_text)\n                self._gpu_msg(i, 45, \"特征就绪 %s\" % \"+\".join(r[\"modes\"]))\n                return r\n\n            results = await asyncio.gather(*[prep(i, w) for i, w in enumerate(self.tts)])\n            modes = results[0][\"modes\"]\n            # 4. 双卡并行合成测试句:不同克隆模式分配到不同的卡上同时评估,并择优\n            self._set(stage=\"双卡并行合成校验 & 相似度评估\", progress=55)\n            zh = detect_language(ref_text or \"你好\") == \"Chinese\"\n            test = \"今天天气真不错,我们一起去公园散步吧。\" if zh else \"The weather is lovely today, let's take a walk in the park.\"\n            lang = \"Chinese\" if zh else \"English\"\n            ref16 = au.resample(ref, config.SR, 16000)\n            scores: dict[str, float] = {}\n\n            async def one(mi, mode):\n                i = mi % len(self.tts)\n                w = self.tts[i]\n                self._gpu_msg(i, 60, \"合成测试句(%s)\" % mode)\n                wav, sr = await self.synth_collect(w, vid, test, lang, mode)\n                wav = au.postprocess_chunk(wav, sr, au.to_db(au.rms(ref)), True, 0.0)\n                s_ = await self.aux.call(\"sim\", a=ref16, b=au.resample(wav, sr, 16000))\n                self._gpu_msg(i, 90, \"%s 相似度 %.1f%%\" % (mode, s_[\"cosine\"] * 100))\n                return mode, s_[\"cosine\"]\n\n            res = await asyncio.gather(*[one(mi, m) for mi, m in enumerate(modes)], return_exceptions=True)\n            for r in res:\n                if isinstance(r, Exception):\n                    self._log(\"模式评估失败: %s\" % (str(r).strip().splitlines() or [repr(r)])[-1])\n                else:\n                    scores[r[0]] = float(r[1])\n                    self._log(\"模式 %s 说话人相似度 %.2f%%\" % (r[0], r[1] * 100))\n            self._set(progress=88)\n            if not scores:\n                best = modes[0]\n            else:\n                best = max(scores, key=scores.get)\n            sim = scores.get(best)\n            # 5. 生效\n            self.voice = {\n                \"id\": vid, \"ref_path\": str(ref_path), \"ref_file\": ref_path.name, \"ref_text\": ref_text, \"mode\": best,\n                \"similarity\": sim, \"scores\": scores, \"target_rms_db\": au.to_db(au.rms(ref)),\n                \"quality\": quality, \"trained_at\": time.time(), \"modes\": modes,\n                \"lang\": \"Chinese\" if zh else \"English\",\n            }\n            (cur / \"meta.json\").write_text(\n                json.dumps({k: v for k, v in self.voice.items() if k != \"ref_path\"}, ensure_ascii=False), \"utf-8\"\n            )\n            self._set(stage=\"双卡并行生成「思考语气词」缓存(0 延迟首声)\", progress=94)\n            await self._make_fillers()\n            for i in range(len(self.tts)):\n                self._gpu_msg(i, 100, \"完成\")\n            self._set(state=\"done\", stage=\"训练完成\", progress=100, similarity=sim, mode=best, ref_text=ref_text)\n            self._log(\"完成,选用模式 %s,相似度 %s\" % (best, \"%.2f%%\" % (sim * 100) if sim is not None else \"N/A\"))\n        except Exception as e:  # noqa: BLE001\n            msg = str(e).strip().splitlines()[-1] if str(e).strip() else repr(e)\n            self._set(state=\"error\", stage=\"失败\", error=msg)\n            self._log(\"失败: \" + msg)\n            print(e, flush=True)\n\n    # ---------- 语气词缓存 ----------\n    async def _make_fillers(self):\n        self.fillers = []\n        v = self.voice\n        texts = config.FILLERS.get((v or {}).get(\"lang\", \"\"), [])\n        if not texts or not self.ready_tts():\n            return\n\n        async def one(t):\n            w = self._pick_tts()\n            wav, sr = await self.synth_collect(w, v[\"id\"], t, v[\"lang\"], v[\"mode\"])\n            wav = await asyncio.to_thread(au.postprocess_chunk, wav, sr, v.get(\"target_rms_db\"), True, 0.0, self.rng)\n            return {\"text\": t, \"pcm\": au.to_pcm16(wav), \"sr\": sr, \"dur\": len(wav) / sr}\n\n        res = await asyncio.gather(*[one(t) for t in texts], return_exceptions=True)\n        for t, r in zip(texts, res):\n            if isinstance(r, dict) and r[\"dur\"] > 0.15:\n                self.fillers.append(r)\n        print(\"[engine] 语气词缓存 %d/%d 就绪\" % (len(self.fillers), len(texts)), flush=True)\n\n    def pick_filler(self):\n        if not self.fillers:\n            return None\n        n = len(self.fillers)\n        i = np.random.randint(n)\n        if n > 1 and i == self._last_filler:\n            i = (i + 1) % n\n        self._last_filler = i\n        return self.fillers[i]\n\n    # ---------- 语音合成 ----------\n    def _pick_tts(self) -> Worker:\n        ws = self.ready_tts()\n        if not ws:\n            raise RuntimeError(\"TTS 模型尚未就绪\")\n        return min(ws, key=lambda w: (w.inflight, w.busy_ms))\n\n    def _cancel_tts(self):\n        \"\"\"让所有 TTS 卡立刻放弃排队中/进行中的合成(用户点停止或开始新一轮时)。\"\"\"\n        for w in self.tts:\n            w.cancel.value = max(w.cancel.value, w.next_id - 1)\n\n    async def synth_collect(self, w: Worker, voice_id: str, text: str, lang: str, mode: str):\n        \"\"\"整句合成(训练评估/语气词缓存用):收集所有流式块 → (wav, sr)。\"\"\"\n        rid, q = w.submit(\"synth\", voice_id=voice_id, text=text, lang=lang, mode=mode, chunk=config.TTS_CHUNK_NEXT)\n        parts, sr = [], config.SR\n        async for d in w.stream(rid, q):\n            parts.append(d[\"pcm\"])\n            sr = d[\"sr\"]\n        if not parts:\n            raise RuntimeError(\"TTS 没有产出音频\")\n        return np.concatenate(parts).astype(np.float32), sr\n\n    async def synth_stream(self, text: str, first: bool, out: asyncio.Queue):\n        \"\"\"合成一句话:每个流式块经「带状态后处理」后放入 out;结束放入 None。出错放入 {\"error\"}。\"\"\"\n        v = self.voice\n        try:\n            w = self._pick_tts()\n            chunk = config.TTS_CHUNK_FIRST if first else config.TTS_CHUNK_NEXT\n            rid, q = w.submit(\"synth\", voice_id=v[\"id\"], text=text, lang=detect_language(text), mode=v[\"mode\"], chunk=chunk)\n        except Exception as e:  # noqa: BLE001\n            await out.put({\"error\": str(e)})\n            await out.put(None)\n            return\n        post, t0 = None, time.time()\n        try:\n            async for d in w.stream(rid, q):\n                if post is None:\n                    post = au.StreamPost(d[\"sr\"], v.get(\"target_rms_db\"), trim_head=True)\n                pcm = post.feed(d[\"pcm\"])\n                if pcm.size:\n                    await out.put({\"pcm\": au.to_pcm16(pcm), \"sr\": d[\"sr\"], \"dur\": pcm.size / d[\"sr\"], \"gpu\": w.gpu})\n            if post is not None:\n                tail = post.finish()\n                if tail.size:\n                    await out.put({\"pcm\": au.to_pcm16(tail), \"sr\": post.sr, \"dur\": tail.size / post.sr, \"gpu\": w.gpu})\n        except asyncio.CancelledError:\n            w.cancel.value = max(w.cancel.value, rid)\n            raise\n        except Exception as e:  # noqa: BLE001\n            await out.put({\"error\": (str(e).strip().splitlines() or [repr(e)])[-1]})\n        finally:\n            w.busy_ms += (time.time() - t0) * 1000\n            await out.put(None)\n\n    # ---------- 对话 ----------\n    def new_session(self) -> Session:\n        return Session()\n\n    async def run_turn(self, sess: Session, text: str, opts: dict, emit_json, emit_audio):\n        t0 = time.time()\n        sess.turn += 1\n        turn = sess.turn\n        speak_only = opts.get(\"speak_only\", False)\n        breath = float(opts.get(\"breath\", 0.4))\n        long_mode = bool(opts.get(\"long\", False))\n        has_voice = self.voice is not None and bool(self.ready_tts())\n        use_filler = bool(opts.get(\"filler\", True)) and not speak_only\n        stats = {\"turn\": turn, \"chunks\": 0, \"audio_s\": 0.0, \"ttfa_ms\": None, \"body_ttfa_ms\": None, \"llm_first_ms\": None, \"gpu_chunks\": {}, \"filler\": None}\n        filler = self.pick_filler() if (use_filler and has_voice) else None\n        base_idx = 1 if filler else 0\n        await emit_json({\"type\": \"start\", \"turn\": turn, \"voice\": has_voice, \"filler\": bool(filler)})\n        if not has_voice:\n            await emit_json({\"type\": \"notice\", \"text\": \"还没有训练声音,本次只输出文字。请先录制/上传参考语音并点击「开始训练」。\"})\n\n        chunker = SentenceChunker()\n        order: asyncio.Queue = asyncio.Queue()\n\n        async def emitter():\n            idx, n_sent = base_idx, 0\n            while True:\n                sq = await order.get()\n                if sq is None:\n                    return\n                first_piece = True\n                while True:\n                    item = await sq.get()\n                    if item is None:\n                        break\n                    if \"error\" in item:\n                        await emit_json({\"type\": \"warn\", \"text\": \"语音片段合成失败: \" + item[\"error\"][:200]})\n                        continue\n                    if first_piece and n_sent > 0 and n_sent % 2 == 1 and breath > 0.01:\n                        br = au.make_breath(item[\"sr\"], breath, self.rng)\n                        if br.size:\n                            br = np.concatenate([br, np.zeros(int(item[\"sr\"] * 0.03), dtype=np.float32)])\n                            await emit_audio(turn, idx, item[\"sr\"], au.to_pcm16(br))\n                            idx += 1\n                            stats[\"chunks\"] += 1\n                    first_piece = False\n                    if stats[\"body_ttfa_ms\"] is None:\n                        stats[\"body_ttfa_ms\"] = round((time.time() - t0) * 1000)\n                    if stats[\"ttfa_ms\"] is None:\n                        stats[\"ttfa_ms\"] = stats[\"body_ttfa_ms\"]\n                    await emit_audio(turn, idx, item[\"sr\"], item[\"pcm\"])\n                    stats[\"chunks\"] += 1\n                    stats[\"audio_s\"] += item[\"dur\"]\n                    g = \"gpu%d\" % item[\"gpu\"]\n                    stats[\"gpu_chunks\"][g] = stats[\"gpu_chunks\"].get(g, 0) + 1\n                    idx += 1\n                n_sent += 1\n\n        em_task = asyncio.create_task(emitter())\n        if filler:\n            stats[\"ttfa_ms\"] = round((time.time() - t0) * 1000)\n            stats[\"filler\"] = filler[\"text\"]\n            stats[\"chunks\"] += 1\n            stats[\"audio_s\"] += filler[\"dur\"]\n            await emit_audio(turn, 0, filler[\"sr\"], filler[\"pcm\"])\n            await emit_json({\"type\": \"text\", \"delta\": filler[\"text\"].rstrip(\",\") + \",\", \"filler\": True})\n        synth_tasks: list[asyncio.Task] = []\n        n_sub = 0\n\n        def submit(piece: str):\n            nonlocal n_sub\n            if not has_voice:\n                return\n            cleaned = clean_for_tts(piece)\n            if not is_speakable(cleaned):\n                return\n            sq: asyncio.Queue = asyncio.Queue()\n            synth_tasks.append(asyncio.create_task(self.synth_stream(cleaned, n_sub == 0, sq)))\n            n_sub += 1\n            order.put_nowait(sq)\n\n        def abort():\n            for t in synth_tasks:\n                t.cancel()\n            em_task.cancel()\n            self._cancel_tts()\n\n        try:\n            if speak_only:\n                for p in _split_all(text):\n                    submit(p)\n                await emit_json({\"type\": \"text\", \"delta\": text})\n            else:\n                sys_prompt = config.SYSTEM_PROMPT\n                msgs = [{\"role\": \"system\", \"content\": sys_prompt}, *sess.history, {\"role\": \"user\", \"content\": text}]\n                sess.history.append({\"role\": \"user\", \"content\": text})\n                max_new = config.LLM_LONG_TOKENS if long_mode else config.LLM_DEFAULT_TOKENS\n                if filler:\n                    msgs[0][\"content\"] += \"\\n\" + config.FILLER_HINT % filler[\"text\"].rstrip(\",\")\n                if long_mode:\n                    msgs[0][\"content\"] += \"\\n本次请尽可能详尽、完整、有层次地长篇回答。\"\n                if self.llm is None or self.llm.state != \"ready\":\n                    detail = (self.llm.error or \"\") if self.llm else \"\"\n                    raise RuntimeError(\"对话模型尚未加载完成或加载失败。\" + (detail.strip().splitlines()[-1] if detail.strip() else \"请稍候或查看 Kaggle 输出日志\"))\n                rid, q = self.llm.submit(\"chat\", messages=msgs, max_new_tokens=max_new)\n                sess.llm_rid = rid\n                full = []\n                try:\n                    async for delta in self.llm.stream(rid, q):\n                        if stats[\"llm_first_ms\"] is None:\n                            stats[\"llm_first_ms\"] = round((time.time() - t0) * 1000)\n                        full.append(delta)\n                        await emit_json({\"type\": \"text\", \"delta\": delta})\n                        for p in chunker.feed(delta):\n                            submit(p)\n                finally:\n                    if full:\n                        sess.history.append({\"role\": \"assistant\", \"content\": \"\".join(full)})\n                        sess.trim()\n                    elif sess.history and sess.history[-1][\"role\"] == \"user\":\n                        sess.history.pop()  # 没有产出内容 → 不把这条用户消息留在历史里\n                for p in chunker.flush():\n                    submit(p)\n                if not full:\n                    raise RuntimeError(\"对话模型没有返回任何内容\")\n            order.put_nowait(None)\n            await em_task\n            stats[\"total_ms\"] = round((time.time() - t0) * 1000)\n            stats[\"audio_s\"] = round(stats[\"audio_s\"], 2)\n            self.turn_stats = stats\n            await emit_json({\"type\": \"done\", \"turn\": turn, \"stats\": stats})\n        except asyncio.CancelledError:\n            abort()\n            if sess.llm_rid and self.llm:\n                self.llm.cancel.value = max(self.llm.cancel.value, sess.llm_rid)\n            raise\n        except Exception as e:  # noqa: BLE001\n            abort()\n            msg = str(e).strip().splitlines()[-1] if str(e).strip() else repr(e)\n            await emit_json({\"type\": \"error\", \"text\": msg})\n            print(\"[turn] 失败:\\n%s\" % e, flush=True)\n\n    def cancel_turn(self, sess: Session):\n        if sess.llm_rid and self.llm:\n            self.llm.cancel.value = max(self.llm.cancel.value, sess.llm_rid)\n        self._cancel_tts()\n        if sess.task and not sess.task.done():\n            sess.task.cancel()\n\n    # ---------- ASR ----------\n    async def transcribe(self, data: bytes) -> dict:\n        if self.aux is None or self.aux.state != \"ready\":\n            raise RuntimeError(\"语音识别模型尚未就绪\")\n        x = await asyncio.to_thread(au.decode_audio, data, 16000)\n        if x.size < 1600:\n            return {\"text\": \"\"}\n        return await self.aux.call(\"asr\", samples=x)\n\n\ndef _split_all(text: str):\n    c = SentenceChunker()\n    out = c.feed(text)\n    out += c.flush()\n    return out\n\n\ndef pack_audio(turn: int, idx: int, sr: int, pcm: bytes) -> bytes:\n    return struct.pack(\"<IIII\", turn, idx, sr, 0) + pcm\n","server/audio_utils.py":"\"\"\"音频工具:解码、参考音频预处理、输出后处理(去沙沙/无缝衔接/微弱呼吸)。\"\"\"\nimport io\nimport shutil\nimport subprocess\n\nimport numpy as np\n\nfrom . import config\n\nSR = config.SR\n\n\ndef to_db(x: float) -> float:\n    return 20.0 * np.log10(max(float(x), 1e-9))\n\n\ndef rms(x: np.ndarray) -> float:\n    if x.size == 0:\n        return 0.0\n    return float(np.sqrt(np.mean(np.square(x.astype(np.float64)))))\n\n\ndef resample(x: np.ndarray, src: int, dst: int) -> np.ndarray:\n    if src == dst:\n        return x.astype(np.float32)\n    from math import gcd\n\n    from scipy.signal import resample_poly\n\n    g = gcd(src, dst)\n    return resample_poly(x, dst // g, src // g).astype(np.float32)\n\n\ndef decode_audio(data: bytes, sr: int = SR) -> np.ndarray:\n    \"\"\"任意格式(webm/ogg/mp3/wav...)→ 单声道 float32。优先 ffmpeg,失败回退 soundfile。\"\"\"\n    if shutil.which(\"ffmpeg\"):\n        p = subprocess.run(\n            [\"ffmpeg\", \"-v\", \"error\", \"-i\", \"pipe:0\", \"-ac\", \"1\", \"-ar\", str(sr), \"-f\", \"f32le\", \"pipe:1\"],\n            input=data, capture_output=True,\n        )\n        if p.returncode == 0 and p.stdout:\n            return np.frombuffer(p.stdout, dtype=np.float32).copy()\n    import soundfile as sf\n\n    try:\n        x, file_sr = sf.read(io.BytesIO(data), dtype=\"float32\", always_2d=True)\n    except Exception as e:  # noqa: BLE001\n        raise ValueError(\"无法解码音频(服务器缺少 ffmpeg 且格式不被 soundfile 支持): %s\" % e)\n    return resample(x.mean(axis=1), file_sr, sr)\n\n\ndef highpass(x: np.ndarray, sr: int, cutoff: float = 60.0) -> np.ndarray:\n    from scipy.signal import butter, sosfiltfilt\n\n    sos = butter(2, cutoff, btype=\"highpass\", fs=sr, output=\"sos\")\n    return sosfiltfilt(sos, x).astype(np.float32)\n\n\ndef _frame_db(x: np.ndarray, sr: int, ms: int = 20) -> np.ndarray:\n    n = max(1, int(sr * ms / 1000))\n    k = len(x) // n\n    if k == 0:\n        return np.array([to_db(rms(x))])\n    fr = x[: k * n].reshape(k, n)\n    return 20 * np.log10(np.sqrt(np.mean(fr.astype(np.float64) ** 2, axis=1)) + 1e-9)\n\n\ndef trim_silence(x: np.ndarray, sr: int, margin_db: float = 38.0, keep_ms: int = 60, tail_ms: int = 120) -> np.ndarray:\n    if x.size == 0:\n        return x\n    db = _frame_db(x, sr)\n    thr = db.max() - margin_db\n    idx = np.where(db > thr)[0]\n    if idx.size == 0:\n        return x\n    n = int(sr * 0.02)\n    s = max(0, idx[0] * n - int(sr * keep_ms / 1000))\n    e = min(len(x), (idx[-1] + 1) * n + int(sr * tail_ms / 1000))\n    return x[s:e]\n\n\ndef analyze_quality(x: np.ndarray, sr: int) -> dict:\n    db = _frame_db(x, sr)\n    noise = np.percentile(db, 10)\n    sig = np.percentile(db, 90)\n    return {\n        \"duration\": round(len(x) / sr, 2),\n        \"snr_db\": round(float(sig - noise), 1),\n        \"rms_db\": round(to_db(rms(x)), 1),\n        \"clip_ratio\": round(float(np.mean(np.abs(x) > 0.99)), 4),\n    }\n\n\ndef preprocess_reference(x: np.ndarray, sr: int = SR, max_seconds: float = 20.0):\n    \"\"\"参考音频清洗。返回 (处理后音频, 质量报告, 警告列表)。\"\"\"\n    warnings = []\n    x = x.astype(np.float32)\n    x = x - float(np.mean(x))\n    x = highpass(x, sr, 60.0)\n    q0 = analyze_quality(x, sr)\n    if q0[\"snr_db\"] < 28:\n        try:\n            import noisereduce as nr\n\n            strength = 0.85 if q0[\"snr_db\"] < 18 else 0.6\n            x = nr.reduce_noise(y=x, sr=sr, stationary=True, prop_decrease=strength).astype(np.float32)\n        except Exception as e:  # noqa: BLE001\n            warnings.append(\"降噪不可用: %s\" % e)\n    x = trim_silence(x, sr, margin_db=40.0, keep_ms=150, tail_ms=250)\n    max_n = int(max_seconds * sr)\n    if len(x) > max_n:\n        # 在 max_seconds 附近找能量最低点截断,避免断在字中间\n        lo, hi = int((max_seconds - 2.5) * sr), max_n\n        n = int(sr * 0.02)\n        seg = x[lo:hi]\n        k = len(seg) // n\n        fr = np.sqrt(np.mean(seg[: k * n].reshape(k, n) ** 2, axis=1))\n        cut = lo + int(np.argmin(fr)) * n\n        x = x[:cut]\n    peak = float(np.max(np.abs(x)) + 1e-9)\n    x = x * (0.9 / peak)\n    q = analyze_quality(x, sr)\n    if q[\"duration\"] < 3:\n        warnings.append(\"参考音频过短(%.1fs),建议 8~20 秒\" % q[\"duration\"])\n    elif q[\"duration\"] < 8:\n        warnings.append(\"参考音频偏短(%.1fs),8~20 秒效果最佳\" % q[\"duration\"])\n    if q0[\"snr_db\"] < 18:\n        warnings.append(\"环境噪声较大(信噪比约 %.0fdB),建议在安静环境重录\" % q0[\"snr_db\"])\n    if q0[\"clip_ratio\"] > 0.002:\n        warnings.append(\"录音有爆音/削波,请降低音量或远离麦克风\")\n    q[\"snr_db_raw\"] = q0[\"snr_db\"]\n    return x, q, warnings\n\n\ndef make_breath(sr: int, level: float, rng: np.random.Generator) -> np.ndarray:\n    \"\"\"极弱的吸气声(带通噪声 + 起伏包络)。level 0~1,0 表示关闭。\"\"\"\n    if level <= 0.01:\n        return np.zeros(0, dtype=np.float32)\n    from scipy.signal import butter, sosfilt\n\n    n = int(sr * rng.uniform(0.22, 0.32))\n    noise = rng.standard_normal(n)\n    sos = butter(2, [300, 3200], btype=\"bandpass\", fs=sr, output=\"sos\")\n    b = sosfilt(sos, noise)\n    t = np.linspace(0, 1, n)\n    env = np.sin(np.pi * t) ** 2 * (0.55 + 0.45 * t)\n    b = b * env\n    b = b / (np.max(np.abs(b)) + 1e-9)\n    amp = 10 ** ((-52.0 + 14.0 * min(level, 1.0)) / 20.0)\n    return (b * amp).astype(np.float32)\n\n\ndef postprocess_chunk(\n    wav: np.ndarray,\n    sr: int,\n    target_rms_db: float | None,\n    first: bool,\n    breath_level: float = 0.4,\n    rng: np.random.Generator | None = None,\n) -> np.ndarray:\n    \"\"\"对每个 TTS 片段做:去直流 → 60Hz 高通 → 修剪首尾静音 → 统一响度 → 淡入淡出 → 软限幅。\"\"\"\n    rng = rng or np.random.default_rng()\n    x = np.asarray(wav, dtype=np.float32).reshape(-1)\n    if x.size < int(sr * 0.05):\n        return x\n    x = x - float(np.mean(x))\n    x = highpass(x, sr, 60.0)\n    x = trim_silence(x, sr, margin_db=42.0, keep_ms=30 if first else 70, tail_ms=90)\n    if target_rms_db is not None:\n        cur = to_db(rms(x))\n        gain = float(np.clip(10 ** ((target_rms_db - cur) / 20.0), 0.4, 2.5))\n        x = x * gain\n    fade = int(sr * 0.008)\n    if x.size > fade * 2:\n        x[:fade] *= np.linspace(0, 1, fade, dtype=np.float32)\n        x[-fade:] *= np.linspace(1, 0, fade, dtype=np.float32)\n    x = np.tanh(x * 1.1) / np.tanh(1.1)  # 软限幅,避免削波爆音\n    if not first and breath_level > 0.01:\n        br = make_breath(sr, breath_level, rng)\n        if br.size:\n            x = np.concatenate([br, np.zeros(int(sr * 0.04), dtype=np.float32), x])\n    return x.astype(np.float32)\n\n\nclass StreamPost:\n    \"\"\"流式后处理(逐块、带状态,块与块之间无缝、无爆音)。\n\n    - 60Hz 二阶高通(带滤波器状态,跨块连续) → 去直流/低频噪声\n    - 响度:用第一块里「有声部分」估算一次增益,整句保持不变(避免逐块忽大忽小造成颤音/沙沙感)\n    - 句首 10ms 淡入;每块保留最后 8ms 暂不发送,与下一块拼接 → 句末才做淡出,中途零接缝\n    - tanh 软限幅,避免削波爆音\n    \"\"\"\n\n    TAIL = int(SR * 0.008)\n\n    def __init__(self, sr: int, target_rms_db: float | None, trim_head: bool = True):\n        from scipy.signal import butter, sosfilt_zi\n\n        self.sr = sr\n        self.target = target_rms_db\n        self.sos = butter(2, 60.0, btype=\"highpass\", fs=sr, output=\"sos\")\n        self.zi = sosfilt_zi(self.sos) * 0.0\n        self.gain = None\n        self.tail = np.zeros(0, dtype=np.float32)\n        self.first = True\n        self.trim_head = trim_head\n        self.sent = 0\n\n    def _gain_from(self, x: np.ndarray) -> float:\n        if self.target is None:\n            return 1.0\n        db = _frame_db(x, self.sr)\n        voiced = db > (db.max() - 30.0)\n        n = max(1, int(self.sr * 0.02))\n        k = len(x) // n\n        if k == 0 or not voiced.any():\n            return 1.0\n        fr = x[: k * n].reshape(k, n)[voiced[:k]]\n        cur = to_db(rms(fr))\n        return float(np.clip(10 ** ((self.target - cur) / 20.0), 0.4, 2.5))\n\n    def feed(self, chunk: np.ndarray) -> np.ndarray:\n        from scipy.signal import sosfilt\n\n        x = np.asarray(chunk, dtype=np.float32).reshape(-1)\n        if x.size == 0:\n            return x\n        x, self.zi = sosfilt(self.sos, x, zi=self.zi)\n        x = x.astype(np.float32)\n        if self.first:\n            if self.trim_head:  # 去掉模型输出开头的静音/杂音,更快出声\n                db = _frame_db(x, self.sr)\n                idx = np.where(db > db.max() - 40.0)[0]\n                if idx.size:\n                    cut = max(0, idx[0] * int(self.sr * 0.02) - int(self.sr * 0.02))\n                    x = x[cut:]\n            if x.size == 0:\n                return x\n            self.gain = self._gain_from(x)\n            f = min(int(self.sr * 0.010), x.size)\n            x[:f] *= np.linspace(0, 1, f, dtype=np.float32)\n            self.first = False\n        if self.gain is None:\n            self.gain = 1.0\n        x = x * self.gain\n        x = np.tanh(x * 1.1) / np.tanh(1.1)\n        x = np.concatenate([self.tail, x.astype(np.float32)])\n        if x.size <= self.TAIL:\n            self.tail = x\n            return np.zeros(0, dtype=np.float32)\n        out, self.tail = x[: -self.TAIL], x[-self.TAIL:]\n        self.sent += out.size\n        return out\n\n    def finish(self) -> np.ndarray:\n        t = self.tail\n        self.tail = np.zeros(0, dtype=np.float32)\n        if t.size:\n            t = t.copy()\n            t *= np.linspace(1, 0, t.size, dtype=np.float32)\n        return t\n\n\ndef to_pcm16(x: np.ndarray) -> bytes:\n    return (np.clip(x, -1.0, 1.0) * 32767.0).astype(\"<i2\").tobytes()\n\n\ndef write_wav(path, x: np.ndarray, sr: int = SR) -> None:\n    import soundfile as sf\n\n    sf.write(str(path), x, sr, subtype=\"PCM_16\")\n","server/app.py":"\"\"\"FastAPI 入口。  启动: python -m uvicorn server.app:app --host 0.0.0.0 --port 7860\"\"\"\nimport asyncio\nimport json\nfrom pathlib import Path\nfrom contextlib import asynccontextmanager\n\nfrom fastapi import FastAPI, File, Form, HTTPException, Request, UploadFile, WebSocket, WebSocketDisconnect\nfrom fastapi.middleware.cors import CORSMiddleware\nfrom fastapi.responses import FileResponse, JSONResponse\n\nfrom . import config\nfrom .engine import Engine, pack_audio\n\nengine = Engine()\n\n\n@asynccontextmanager\nasync def lifespan(_: FastAPI):\n    await engine.start()\n    yield\n    for w in engine.workers:\n        w.stop()\n\n\napp = FastAPI(title=\"Voice Clone Studio\", lifespan=lifespan)\napp.add_middleware(CORSMiddleware, allow_origins=[\"*\"], allow_methods=[\"*\"], allow_headers=[\"*\"])\n\n\n@app.middleware(\"http\")\nasync def allow_embed(request: Request, call_next):\n    resp = await call_next(request)\n    # 允许被「浏览器模拟器」iframe 嵌入,并允许麦克风/自动播放(已移除摄像头)\n    resp.headers[\"Content-Security-Policy\"] = \"frame-ancestors *\"\n    resp.headers[\"Permissions-Policy\"] = \"microphone=*, autoplay=*\"\n    resp.headers[\"Cache-Control\"] = \"no-store\"\n    if \"x-frame-options\" in resp.headers:\n        del resp.headers[\"x-frame-options\"]\n    return resp\n\n\n@app.get(\"/\")\nasync def index():\n    return FileResponse(config.WEB_DIR / \"index.html\", media_type=\"text/html; charset=utf-8\")\n\n\n@app.get(\"/api/health\")\nasync def health():\n    return {\"ok\": True, \"mock\": config.MOCK}\n\n\n@app.get(\"/api/status\")\nasync def status():\n    return engine.status()\n\n\n@app.post(\"/api/voice/train\")\nasync def train(file: UploadFile = File(...), text: str = Form(\"\")):\n    data = await file.read()\n    if len(data) < 2000:\n        raise HTTPException(400, \"音频文件为空或太小\")\n    try:\n        await engine.start_training(data, text)\n    except RuntimeError as e:\n        raise HTTPException(409, str(e))\n    return {\"ok\": True}\n\n\n@app.get(\"/api/voice/job\")\nasync def job():\n    return engine.job\n\n\n@app.get(\"/api/voice/ref.wav\")\nasync def ref_wav():\n    v = engine.voice\n    p = Path(v[\"ref_path\"]) if v and v.get(\"ref_path\") else config.VOICE_DIR / \"current\" / \"ref.wav\"\n    if not p.exists():\n        raise HTTPException(404, \"尚无参考音频\")\n    return FileResponse(p, media_type=\"audio/wav\")\n\n\n@app.post(\"/api/asr\")\nasync def asr(request: Request):\n    data = await request.body()\n    try:\n        return await engine.transcribe(data)\n    except Exception as e:  # noqa: BLE001\n        return JSONResponse({\"error\": str(e).strip().splitlines()[-1]}, status_code=500)\n\n\n@app.websocket(\"/ws\")\nasync def ws_endpoint(ws: WebSocket):\n    await ws.accept()\n    sess = engine.new_session()\n    lock = asyncio.Lock()\n\n    async def send_json(obj):\n        async with lock:\n            await ws.send_text(json.dumps(obj, ensure_ascii=False))\n\n    async def send_audio(turn, idx, sr, pcm):\n        async with lock:\n            await ws.send_bytes(pack_audio(turn, idx, sr, pcm))\n\n    async def guarded(coro):\n        try:\n            await coro\n        except asyncio.CancelledError:\n            pass\n        except Exception as e:  # noqa: BLE001  任何意外都要让界面看到,绝不静默\n            try:\n                await send_json({\"type\": \"error\", \"text\": \"服务端异常: \" + (str(e).strip().splitlines() or [repr(e)])[-1]})\n            except Exception:  # noqa: BLE001\n                pass\n\n    try:\n        while True:\n            msg = json.loads(await ws.receive_text())\n            t = msg.get(\"type\")\n            if t == \"ping\":\n                await send_json({\"type\": \"pong\"})\n            elif t in (\"chat\", \"speak\"):\n                engine.cancel_turn(sess)\n                if sess.task:\n                    try:\n                        await asyncio.wait_for(asyncio.shield(sess.task), timeout=0.5)\n                    except Exception:  # noqa: BLE001\n                        pass\n                text = str(msg.get(\"text\", \"\")).strip()\n                if not text:\n                    continue\n                opts = dict(msg.get(\"opts\") or {})\n                opts[\"speak_only\"] = t == \"speak\"\n                sess.task = asyncio.create_task(guarded(engine.run_turn(sess, text, opts, send_json, send_audio)))\n            elif t == \"stop\":\n                engine.cancel_turn(sess)\n                await send_json({\"type\": \"stopped\"})\n            elif t == \"reset\":\n                engine.cancel_turn(sess)\n                sess.history.clear()\n                await send_json({\"type\": \"reset\"})\n    except WebSocketDisconnect:\n        pass\n    except Exception:  # noqa: BLE001\n        pass\n    finally:\n        engine.cancel_turn(sess)\n","server/config.py":"\"\"\"全局配置。所有项都可以用环境变量覆盖。\"\"\"\nimport os\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parent.parent\nDATA_DIR = Path(os.environ.get(\"CLONE_DATA\", ROOT / \"data\"))\nVOICE_DIR = DATA_DIR / \"voices\"\nWEB_DIR = ROOT / \"web\"\nVOICE_DIR.mkdir(parents=True, exist_ok=True)\n\n# CLONE_MOCK=1 时不加载任何真实模型,用于在没有 GPU 的机器上验证整条链路。\nMOCK = os.environ.get(\"CLONE_MOCK\", \"0\") == \"1\"\nPORT = int(os.environ.get(\"PORT\", \"7860\"))\n\n# ---- 模型(全部常驻显存:服务进程不退出,模型就不会卸载) ----\nTTS_MODEL = os.environ.get(\"TTS_MODEL\", \"Qwen/Qwen3-TTS-12Hz-1.7B-Base\")\nLLM_MODEL = os.environ.get(\"LLM_MODEL\", \"Qwen/Qwen3-4B-Instruct-2507\")\nASR_MODEL = os.environ.get(\"ASR_MODEL\", \"openai/whisper-large-v3-turbo\")\nSV_MODEL = os.environ.get(\"SV_MODEL\", \"microsoft/wavlm-base-plus-sv\")\n\nSR = 24000  # Qwen3-TTS 输出采样率\nLLM_DEFAULT_TOKENS = int(os.environ.get(\"LLM_DEFAULT_TOKENS\", \"1024\"))\nLLM_LONG_TOKENS = int(os.environ.get(\"LLM_LONG_TOKENS\", \"4096\"))\nHISTORY_CHARS = int(os.environ.get(\"HISTORY_CHARS\", \"7000\"))\nLLM_FIRST_TOKEN_TIMEOUT = float(os.environ.get(\"LLM_FIRST_TOKEN_TIMEOUT\", \"60\"))  # 秒,超时必给出错误,绝不静默卡死\nLLM_STALL_TIMEOUT = float(os.environ.get(\"LLM_STALL_TIMEOUT\", \"45\"))\n\n# ---- 流式 TTS ----\n# faster-qwen3-tts: CUDA Graph + 流式输出。chunk=4 步 ≈ 0.33s 音频,首块越小首声越快。\nTTS_STREAM = os.environ.get(\"TTS_STREAM\", \"1\") == \"1\"\nTTS_CHUNK_FIRST = int(os.environ.get(\"TTS_CHUNK_FIRST\", \"4\"))\nTTS_CHUNK_NEXT = int(os.environ.get(\"TTS_CHUNK_NEXT\", \"8\"))\n\n# ---- 分句策略 (决定首声延迟) ----\nFIRST_MIN_CHARS = int(os.environ.get(\"FIRST_MIN_CHARS\", \"3\"))\nFIRST_MAX_CHARS = int(os.environ.get(\"FIRST_MAX_CHARS\", \"14\"))\nNEXT_MIN_CHARS = int(os.environ.get(\"NEXT_MIN_CHARS\", \"14\"))\nNEXT_MAX_CHARS = int(os.environ.get(\"NEXT_MAX_CHARS\", \"48\"))\n\nSYSTEM_PROMPT = (\n    \"你是一个温暖、自然、有情绪的中文语音助手,你的回答会被直接转成语音朗读。\"\n    \"请使用口语化的纯文本回答:不要使用 Markdown、列表符号、表情符号、代码块和网址。\"\n    \"句子要自然分段,多用逗号和句号,适当使用语气词(嗯、啊、呢、吧)表达情绪。\"\n    \"每次回答的第一个分句要非常短(不超过 8 个字),然后再自然展开。\"\n    \"如果用户使用其他语言,就用对应语言回答。\"\n    \"当用户要求长篇内容(故事、文章、讲解)时,请完整、连贯、有条理地充分展开,不要中途停止。\"\n)\n\nTTS_DTYPE = os.environ.get(\"TTS_DTYPE\", \"float16\")  # T4 无原生 bf16;若输出异常会自动回退 bfloat16\nLLM_DTYPE = os.environ.get(\"LLM_DTYPE\", \"float16\")\n\n# 预合成并缓存的「思考语气词」(用克隆声音生成,每轮对话 0 延迟先播,正文在后台同步合成)\nFILLERS = {\n    \"Chinese\": [\"嗯,\", \"好的,\", \"让我想想,\", \"哦,\", \"嗯嗯,\"],\n    \"English\": [\"Hmm,\", \"Well,\", \"Okay,\", \"Sure,\", \"Let me think,\"],\n}\nFILLER_HINT = \"(系统已经替你先说了一个简短的语气词「%s」,你的正文请直接接着回答,不要再用语气词开头。)\"\n","server/text_chunker.py":"\"\"\"流式文本 → 适合 TTS 的短句。\n\n首句尽量短,以换取 3 秒内出首声;后续句子适当变长,让韵律更自然。\n\"\"\"\nimport re\n\nfrom . import config\n\nSTRONG = \"。！？!?；;\\n…\"\nWEAK = \",，、:：—\"\n\n_EMOJI = re.compile(\n    \"[\\U0001F300-\\U0001FAFF\\U00002600-\\U000027BF\\U0001F000-\\U0001F2FF\\U0000FE0F\\U0000200D]+\",\n    flags=re.UNICODE,\n)\n_CODE = re.compile(r\"```.*?```\", re.S)\n_LINK = re.compile(r\"\\[([^\\]]*)\\]\\([^)]*\\)\")\n_URL = re.compile(r\"https?://\\S+\")\n_MD = re.compile(r\"[*_#>`~|]+\")\n_BULLET = re.compile(r\"^\\s*(?:[-+•]|\\d+[.、)])\\s+\", re.M)\n_SPEAKABLE = re.compile(r\"[0-9A-Za-z\\u4e00-\\u9fff\\u3040-\\u30ff\\uac00-\\ud7af]\")\n\n\ndef clean_for_tts(text: str) -> str:\n    text = _CODE.sub(\"。\", text)\n    text = _LINK.sub(r\"\\1\", text)\n    text = _URL.sub(\"\", text)\n    text = _BULLET.sub(\"\", text)\n    text = _EMOJI.sub(\"\", text)\n    text = _MD.sub(\"\", text)\n    text = re.sub(r\"[ \\t]+\", \" \", text)\n    text = re.sub(r\"\\s*\\n\\s*\", \"。\", text) if \"\\n\" in text else text\n    text = re.sub(r\"[。]{2,}\", \"。\", text)\n    return text.strip()\n\n\ndef is_speakable(text: str) -> bool:\n    return bool(_SPEAKABLE.search(text))\n\n\ndef detect_language(text: str) -> str:\n    cjk = len(re.findall(r\"[\\u4e00-\\u9fff]\", text))\n    kana = len(re.findall(r\"[\\u3040-\\u30ff]\", text))\n    hangul = len(re.findall(r\"[\\uac00-\\ud7af]\", text))\n    latin = len(re.findall(r\"[A-Za-z]\", text))\n    if kana > 0 and kana >= cjk * 0.3:\n        return \"Japanese\"\n    if hangul > 0:\n        return \"Korean\"\n    if cjk >= max(1, latin // 3):\n        return \"Chinese\"\n    return \"English\"\n\n\nclass SentenceChunker:\n    def __init__(self) -> None:\n        self.buf = \"\"\n        self.count = 0  # 已产出的片段数\n\n    def _limits(self):\n        if self.count == 0:\n            return config.FIRST_MIN_CHARS, config.FIRST_MAX_CHARS\n        return config.NEXT_MIN_CHARS, config.NEXT_MAX_CHARS\n\n    def _cut(self, final: bool = False):\n        buf = self.buf\n        if not buf.strip():\n            return None\n        min_len, max_len = self._limits()\n        first = self.count == 0\n        # 1) 强标点\n        for i, ch in enumerate(buf):\n            if ch in STRONG and i + 1 >= min_len:\n                return i + 1\n        # 2) 首句允许弱标点,抢首声\n        if first:\n            for i, ch in enumerate(buf):\n                if ch in WEAK and i + 1 >= min_len:\n                    return i + 1\n        # 3) 超长强制切分\n        if len(buf) >= max_len:\n            cut = -1\n            for i in range(min(len(buf), max_len) - 1, min_len - 1, -1):\n                if buf[i] in WEAK or buf[i] == \" \":\n                    cut = i + 1\n                    break\n            return cut if cut > 0 else max_len\n        if final:\n            return len(buf)\n        return None\n\n    def feed(self, delta: str):\n        self.buf += delta\n        out = []\n        while True:\n            cut = self._cut()\n            if not cut:\n                break\n            piece, self.buf = self.buf[:cut], self.buf[cut:]\n            piece = piece.strip()\n            if piece:\n                self.count += 1\n                out.append(piece)\n        return out\n\n    def flush(self):\n        out = []\n        while self.buf.strip():\n            cut = self._cut(final=True) or len(self.buf)\n            piece, self.buf = self.buf[:cut], self.buf[cut:]\n            piece = piece.strip()\n            if piece:\n                self.count += 1\n                out.append(piece)\n        self.buf = \"\"\n        return out\n","server/__init__.py":"\"\"\"克隆语音系统 · 服务端包 (Kaggle T4x2)。\"\"\"\n","web/index.html":"<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\" />\n<title>Voice Clone Studio · 克隆语音系统</title>\n<style>\n  :root{\n    --bg:#070b17; --panel:rgba(255,255,255,.055); --line:rgba(255,255,255,.09);\n    --txt:#e8ecff; --mut:#8c95b8; --a1:#7c5cff; --a2:#22d3ee; --ok:#34d399; --warn:#fbbf24; --bad:#fb7185;\n  }\n  *{box-sizing:border-box;margin:0;padding:0}\n  html,body{height:100%;overflow:hidden;background:var(--bg);color:var(--txt);\n    font-family:-apple-system,BlinkMacSystemFont,\"PingFang SC\",\"Microsoft YaHei\",\"Segoe UI\",sans-serif;font-size:14px}\n  body::before{content:\"\";position:fixed;inset:-20%;z-index:-1;\n    background:radial-gradient(600px 400px at 15% 10%,rgba(124,92,255,.28),transparent 60%),\n               radial-gradient(700px 500px at 90% 85%,rgba(34,211,238,.18),transparent 60%),\n               radial-gradient(500px 400px at 60% 0%,rgba(244,114,182,.10),transparent 60%);}\n  button{font:inherit;color:inherit;cursor:pointer;border:0;background:none}\n  .app{height:100dvh;display:grid;grid-template-rows:58px 1fr;gap:10px;padding:10px}\n  /* header */\n  header{display:flex;align-items:center;gap:14px;padding:0 16px;border-radius:16px;background:var(--panel);\n    border:1px solid var(--line);backdrop-filter:blur(14px)}\n  .logo{display:flex;align-items:center;gap:10px;font-weight:700;letter-spacing:.3px;font-size:16px;white-space:nowrap}\n  .logo i{width:30px;height:30px;border-radius:10px;display:grid;place-items:center;font-style:normal;\n    background:linear-gradient(135deg,var(--a1),var(--a2));box-shadow:0 6px 20px rgba(124,92,255,.45)}\n  .sp{flex:1}\n  .chip{display:flex;align-items:center;gap:8px;padding:6px 11px;border-radius:12px;background:rgba(255,255,255,.05);\n    border:1px solid var(--line);font-size:12px;color:var(--mut);white-space:nowrap}\n  .chip b{color:var(--txt);font-weight:600}\n  .dot{width:8px;height:8px;border-radius:50%;background:var(--mut)}\n  .dot.ok{background:var(--ok);box-shadow:0 0 8px var(--ok)} .dot.load{background:var(--warn);animation:blink 1s infinite}\n  .dot.err{background:var(--bad)}\n  @keyframes blink{50%{opacity:.25}}\n  .gbar{width:46px;height:6px;border-radius:4px;background:rgba(255,255,255,.1);overflow:hidden}\n  .gbar>i{display:block;height:100%;background:linear-gradient(90deg,var(--a1),var(--a2));width:0;transition:width .5s}\n  /* layout */\n  main{min-height:0;display:grid;grid-template-columns:380px minmax(0,1fr);gap:10px}\n  .card{min-height:0;display:flex;flex-direction:column;border-radius:18px;background:var(--panel);border:1px solid var(--line);\n    backdrop-filter:blur(14px);padding:14px;gap:10px;overflow:hidden}\n  .card h2{font-size:13px;font-weight:600;letter-spacing:.4px;display:flex;align-items:center;gap:8px;color:#cfd6ff}\n  .card h2 em{font-style:normal;font-size:11px;color:var(--mut);font-weight:400;margin-left:auto}\n  .num{width:20px;height:20px;border-radius:7px;display:grid;place-items:center;font-size:11px;background:linear-gradient(135deg,var(--a1),var(--a2));color:#fff}\n  .btn{padding:9px 14px;border-radius:12px;background:rgba(255,255,255,.07);border:1px solid var(--line);transition:.15s;font-weight:500;white-space:nowrap}\n  .btn:hover{background:rgba(255,255,255,.12);transform:translateY(-1px)}\n  .btn:disabled{opacity:.45;cursor:not-allowed;transform:none}\n  .btn.pri{background:linear-gradient(135deg,var(--a1),#5b8cff 55%,var(--a2));border:0;color:#fff;box-shadow:0 8px 24px rgba(91,140,255,.35)}\n  .btn.pri:hover{filter:brightness(1.1)}\n  .btn.danger{background:rgba(251,113,133,.16);border-color:rgba(251,113,133,.4);color:#ffd1d8}\n  /* left: clone */\n  .script{padding:10px 12px;border-radius:12px;background:rgba(0,0,0,.25);border:1px dashed rgba(255,255,255,.14);\n    font-size:12.5px;line-height:1.65;color:#cdd3f5;position:relative}\n  .script small{display:block;color:var(--mut);margin-bottom:4px;font-size:11px;padding-right:48px}\n  .script button{position:absolute;right:8px;top:6px;font-size:11px;color:var(--a2)}\n  .recrow{display:flex;align-items:center;gap:12px}\n  .rec{width:62px;height:62px;border-radius:50%;flex:none;display:grid;place-items:center;font-size:24px;\n    background:radial-gradient(circle at 30% 30%,#ff7a8c,#e11d48);box-shadow:0 8px 26px rgba(225,29,72,.45);transition:.2s}\n  .rec.on{animation:pulse 1.1s infinite;background:radial-gradient(circle at 30% 30%,#fff,#fb7185)}\n  @keyframes pulse{0%{box-shadow:0 0 0 0 rgba(251,113,133,.65)}100%{box-shadow:0 0 0 22px rgba(251,113,133,0)}}\n  canvas.wave{flex:1;height:62px;border-radius:12px;background:rgba(0,0,0,.28);width:100%}\n  .row{display:flex;gap:8px;align-items:center}\n  .row .btn{flex:1}\n  textarea.t,input.t{width:100%;border-radius:12px;background:rgba(0,0,0,.28);border:1px solid var(--line);color:var(--txt);\n    padding:9px 12px;font:inherit;outline:none;resize:none}\n  textarea.t:focus,input.t:focus{border-color:rgba(124,92,255,.7)}\n  audio{width:100%;height:32px}\n  .prog{height:8px;border-radius:6px;background:rgba(255,255,255,.08);overflow:hidden}\n  .prog>i{display:block;height:100%;width:0;background:linear-gradient(90deg,var(--a1),var(--a2));transition:width .4s}\n  .gpuline{display:grid;grid-template-columns:48px 1fr;gap:4px 8px;align-items:center;font-size:11.5px;color:var(--mut)}\n  .gpuline span.m{grid-column:1/3;margin-top:-2px;color:#b9c1ea}\n  .result{display:flex;align-items:center;gap:12px;padding:10px;border-radius:14px;background:rgba(52,211,153,.08);border:1px solid rgba(52,211,153,.25)}\n  .ring{--p:0;width:58px;height:58px;border-radius:50%;flex:none;display:grid;place-items:center;font-weight:700;font-size:13px;\n    background:conic-gradient(var(--ok) calc(var(--p)*1%),rgba(255,255,255,.1) 0)}\n  .ring span{width:46px;height:46px;border-radius:50%;background:#0d1328;display:grid;place-items:center}\n  .warns{font-size:11.5px;color:var(--warn);line-height:1.5}\n  /* center: chat */\n  #msgs{flex:1;min-height:0;overflow-y:auto;display:flex;flex-direction:column;gap:10px;padding:2px 4px;scroll-behavior:smooth}\n  #msgs::-webkit-scrollbar{width:0}\n  .msg{max-width:84%;padding:10px 14px;border-radius:16px;line-height:1.7;white-space:pre-wrap;word-break:break-word;font-size:14.5px;animation:in .25s}\n  @keyframes in{from{opacity:0;transform:translateY(6px)}}\n  .msg.u{align-self:flex-end;background:linear-gradient(135deg,rgba(124,92,255,.85),rgba(91,140,255,.8));border-bottom-right-radius:5px}\n  .msg.a{align-self:flex-start;background:rgba(255,255,255,.07);border:1px solid var(--line);border-bottom-left-radius:5px}\n  .msg.e{align-self:center;font-size:12.5px;color:#ffd1d8;background:rgba(251,113,133,.14);border:1px solid rgba(251,113,133,.4);max-width:92%}\n  .msg.s{align-self:center;font-size:12px;color:var(--mut);background:none;padding:2px}\n  .msg.a.live::after{content:\"▍\";color:var(--a2);animation:blink 1s infinite}\n  .empty{margin:auto;text-align:center;color:var(--mut);line-height:2}\n  .empty b{display:block;font-size:20px;color:var(--txt);margin-bottom:4px}\n  .bar{display:flex;gap:8px;align-items:center}\n  .iconbtn{width:44px;height:44px;border-radius:14px;flex:none;display:grid;place-items:center;font-size:19px;background:rgba(255,255,255,.07);border:1px solid var(--line)}\n  .iconbtn.on{background:rgba(251,113,133,.25);border-color:var(--bad);animation:pulse 1.1s infinite}\n  .opts{display:flex;gap:8px;flex-wrap:wrap;align-items:center;font-size:12px;color:var(--mut)}\n  .tg{display:flex;align-items:center;gap:6px;padding:5px 10px;border-radius:10px;background:rgba(255,255,255,.05);border:1px solid var(--line);cursor:pointer;user-select:none}\n  .tg.on{color:#fff;background:rgba(124,92,255,.28);border-color:rgba(124,92,255,.7)}\n  input[type=range]{accent-color:var(--a1);width:70px}\n  #viz{height:26px;width:90px;border-radius:8px;background:rgba(0,0,0,.25)}\n  .state{display:flex;align-items:center;gap:8px;margin-left:auto}\n  /* right: detect */\n  .vid{position:relative;border-radius:14px;overflow:hidden;background:#000;aspect-ratio:4/3;flex:none}\n  .vid video,.vid canvas{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}\n  .vid .ph{position:absolute;inset:0;display:grid;place-items:center;color:var(--mut);font-size:12px;text-align:center;line-height:1.8}\n  #chips{display:flex;flex-wrap:wrap;gap:6px;align-content:flex-start;flex:1;min-height:0;overflow:hidden}\n  .ch{padding:4px 10px;border-radius:999px;font-size:12px;background:rgba(34,211,238,.12);border:1px solid rgba(34,211,238,.35);color:#c9f6ff}\n  .ch i{font-style:normal;color:var(--mut);margin-left:4px}\n  .tabs{display:none}\n  /* overlay */\n  #gate{position:fixed;inset:0;z-index:50;display:grid;place-items:center;background:rgba(5,8,20,.82);backdrop-filter:blur(10px)}\n  #gate .box{text-align:center;max-width:420px;padding:30px}\n  .orb{width:110px;height:110px;border-radius:50%;margin:0 auto 22px;background:radial-gradient(circle at 30% 30%,#fff,var(--a1) 40%,var(--a2));\n    box-shadow:0 0 60px rgba(124,92,255,.7);animation:float 3s ease-in-out infinite}\n  @keyframes float{50%{transform:translateY(-8px) scale(1.04)}}\n  #gate h1{font-size:24px;margin-bottom:8px} #gate p{color:var(--mut);line-height:1.8;margin-bottom:22px}\n  #toast{position:fixed;left:50%;bottom:22px;transform:translateX(-50%);z-index:60;padding:10px 18px;border-radius:12px;background:#1a2142;\n    border:1px solid var(--line);opacity:0;pointer-events:none;transition:.3s;max-width:80vw}\n  #toast.show{opacity:1}\n  /* narrow screens: tabs, still no scrolling */\n  @media (max-width:1080px){\n    main{grid-template-columns:1fr;grid-template-rows:1fr 48px}\n    .tabs{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;order:2}\n    .tabs button{border-radius:14px;background:var(--panel);border:1px solid var(--line)}\n    .tabs button.on{background:linear-gradient(135deg,var(--a1),var(--a2));border:0}\n    main>.card{display:none;order:1} main[data-tab=\"clone\"]>#c-clone,main[data-tab=\"chat\"]>#c-chat,\n    .hide-n{display:none}\n  }\n</style>\n</head>\n<body>\n<div id=\"gate\"><div class=\"box\">\n  <div class=\"orb\"></div><h1>Voice Clone Studio</h1>\n  <p>双卡 Qwen3-TTS 声音克隆 · 实时对话<br/>点击下方按钮启用声音(浏览器要求一次用户手势才能自动播放)。</p>\n  <button class=\"btn pri\" id=\"enter\" style=\"padding:13px 34px;font-size:16px\">进入系统</button>\n</div></div>\n\n<div class=\"app\">\n  <header>\n    <div class=\"logo\"><i>🎙</i>Voice Clone Studio</div>\n    <div class=\"sp\"></div>\n    <div class=\"chip hide-n\"><span class=\"dot\" id=\"d-conn\"></span>连接 <b id=\"t-conn\">…</b></div>\n    <div class=\"chip hide-n\"><span class=\"dot\" id=\"d-llm\"></span>对话 <b id=\"t-llm\">…</b></div>\n    <div class=\"chip hide-n\"><span class=\"dot\" id=\"d-tts\"></span>语音 <b id=\"t-tts\">…</b></div>\n    <div class=\"chip\" id=\"g0\"><b>GPU0</b><div class=\"gbar\"><i></i></div><span>—</span></div>\n    <div class=\"chip\" id=\"g1\"><b>GPU1</b><div class=\"gbar\"><i></i></div><span>—</span></div>\n    <div class=\"chip\"><span>首声</span><b id=\"ttfa\">—</b></div>\n    <div class=\"chip hide-n\"><span>声音</span><b id=\"vstate\">未训练</b></div>\n  </header>\n\n  <main data-tab=\"chat\" id=\"main\">\n    <!-- ① 克隆 -->\n    <section class=\"card\" id=\"c-clone\">\n      <h2><span class=\"num\">1</span>录制 / 上传参考语音<em id=\"rectime\">00:00</em></h2>\n      <div class=\"script\"><small>请用自然的语气朗读(包含停顿、呼吸与情绪,8~20 秒最佳)</small><span id=\"scriptText\"></span><button id=\"nextScript\">换一段</button></div>\n      <div class=\"recrow\"><button class=\"rec\" id=\"rec\" title=\"开始/停止录音\">🎤</button><canvas class=\"wave\" id=\"wave\"></canvas></div>\n      <div class=\"row\"><button class=\"btn\" id=\"upload\">⬆ 上传音频</button><button class=\"btn\" id=\"clear\">清除</button></div>\n      <input type=\"file\" id=\"file\" accept=\"audio/*,video/*\" hidden />\n      <audio id=\"preview\" controls style=\"display:none\"></audio>\n      <textarea class=\"t\" id=\"reftext\" rows=\"2\" placeholder=\"参考文本(留空 = 自动识别,推荐)\"></textarea>\n      <button class=\"btn pri\" id=\"train\" style=\"padding:12px;font-size:15px\" disabled>🚀 开始训练(双卡同时)</button>\n      <div class=\"prog\"><i id=\"pall\"></i></div>\n      <div class=\"gpuline\" id=\"gl\"></div>\n      <div class=\"result\" id=\"result\" style=\"display:none\"><div class=\"ring\" id=\"ring\"><span id=\"ringv\">—</span></div>\n        <div style=\"font-size:12px;line-height:1.6\"><b id=\"rmode\">—</b><br/><span style=\"color:var(--mut)\" id=\"rinfo\"></span></div></div>\n      <div class=\"warns\" id=\"warns\"></div>\n    </section>\n\n    <!-- ② 对话 -->\n    <section class=\"card\" id=\"c-chat\">\n      <h2><span class=\"num\">2</span>语音对话 · 克隆声音自动朗读<div class=\"state\"><canvas id=\"viz\" width=\"180\" height=\"52\"></canvas><span id=\"pstate\" style=\"font-size:12px;color:var(--mut)\">待机</span></div></h2>\n      <div id=\"msgs\"><div class=\"empty\"><b>先训练声音,再开始聊天</b>打字 · 或点 🎤 直接说话<br/>AI 的回答会用你的克隆声音立即朗读</div></div>\n      <div class=\"opts\">\n        <label class=\"tg on\" id=\"tgAuto\">🔊 自动播放</label>\n        <label class=\"tg on\" id=\"tgSmooth\" title=\"播放中途若合成跟不上,先攒够缓冲再继续,避免卡顿\">🧵 无停顿优先</label>\n        <label class=\"tg on\" id=\"tgFiller\" title=\"用你的克隆声音先说「嗯,」「好的,」,0 延迟出声,正文同时在双卡合成\">💬 语气词先行</label>\n        <label class=\"tg\" id=\"tgLong\">📖 长文模式</label>\n        <label class=\"tg hide-n\">🌬 呼吸 <input type=\"range\" id=\"breath\" min=\"0\" max=\"100\" value=\"40\" /></label>\n        <button class=\"tg\" id=\"reset\">🧹 新对话</button>\n      </div>\n      <div class=\"bar\">\n        <button class=\"iconbtn\" id=\"mic\" title=\"语音输入\">🎙</button>\n        <input class=\"t\" id=\"input\" placeholder=\"输入消息,回车发送 …\" autocomplete=\"off\" />\n        <button class=\"btn pri\" id=\"send\" style=\"height:44px\">发送</button>\n        <button class=\"btn danger\" id=\"stop\" style=\"height:44px\">停止</button>\n      </div>\n    </section>\n\n    <nav class=\"tabs\"><button data-t=\"clone\">🎤 克隆</button><button data-t=\"chat\" class=\"on\">💬 对话</button></nav>\n  </main>\n</div>\n<div id=\"toast\"></div>\n\n<script>\n\"use strict\";\nconst $ = (id) => document.getElementById(id);\nconst toast = (t, ms = 2600) => { const e = $(\"toast\"); e.textContent = t; e.classList.add(\"show\"); clearTimeout(toast.t); toast.t = setTimeout(() => e.classList.remove(\"show\"), ms); };\nconst fmtT = (s) => String(Math.floor(s / 60)).padStart(2, \"0\") + \":\" + String(Math.floor(s % 60)).padStart(2, \"0\");\n\n/* ---------------- 朗读文案 ---------------- */\nconst SCRIPTS = [\n  \"你好呀,今天过得怎么样?我最近发现了一件特别有趣的事情……嗯,让我慢慢讲给你听。先深呼吸,放松一下,别着急。哇,真的太棒了!不过说实话,也有一点点小遗憾呢。好啦,谢谢你一直听我说。\",\n  \"清晨的阳光洒在窗台上,空气里有淡淡的咖啡香。我喜欢这样安静的时刻,慢慢地呼吸,慢慢地想事情。有时候会开心得想笑,有时候也会忽然安静下来,你说,这样的生活是不是很美好?\",\n  \"Hello, it's so good to hear from you! Let me take a deep breath and tell you a little story. It was a quiet evening, and, well, I honestly didn't expect anything special. But then, wow, everything changed.\",\n];\nlet scriptIdx = 0;\nconst showScript = () => { $(\"scriptText\").textContent = SCRIPTS[scriptIdx % SCRIPTS.length]; };\n$(\"nextScript\").onclick = () => { scriptIdx++; showScript(); };\nshowScript();\n\n/* ---------------- 无缝播放器 ---------------- */\nclass GaplessPlayer {\n  constructor() { this.ctx = null; this.hold = 0; this.floor = 1.2; this.reset(); this.onstate = () => {}; this.onfirst = () => {}; }\n  ensure() {\n    if (!this.ctx) {\n      this.ctx = new (window.AudioContext || window.webkitAudioContext)({ latencyHint: \"interactive\" });\n      this.gain = this.ctx.createGain(); this.an = this.ctx.createAnalyser(); this.an.fftSize = 128;\n      this.gain.connect(this.an); this.an.connect(this.ctx.destination);\n    }\n    if (this.ctx.state !== \"running\") this.ctx.resume();\n  }\n  reset() { this.turn = -1; this.pending = new Map(); this.expect = 0; this.total = null; this.nextTime = 0; this.srcs = new Set(); this.waitSince = 0; this.underruns = 0; this.firstDone = false; clearTimeout(this.timer); }\n  newTurn(turn) { this.stop(); this.turn = turn; }\n  stop() {\n    for (const s of this.srcs) { try { s.onended = null; s.stop(); } catch (e) {} }\n    this.reset(); this.onstate(\"idle\");\n  }\n  finish(total) { this.total = total; this.drain(); this.check(); }\n  push(turn, idx, sr, f32) { if (turn !== this.turn) return; this.pending.set(idx, { sr, f32 }); this.drain(); }\n  readyDur() { let d = 0, i = this.expect; while (this.pending.has(i)) { const c = this.pending.get(i); d += c.f32.length / c.sr; i++; } return d; }\n  drain() {\n    if (!this.ctx) return;\n    const now = this.ctx.currentTime;\n    const lead = this.nextTime - now;\n    const idle = this.srcs.size === 0 || lead < 0.01;\n    if (idle && this.pending.has(this.expect)) {\n      const isRe = this.expect > 0;                       // 播放中途断流 → 重新缓冲\n      const need = isRe ? Math.max(this.hold, this.floor) : (this.fillerFirst || !this.floor ? 0 : 0.6);                  // 首句立即播,中途缺料则多攒一点\n      const all = this.total !== null && this.expect + this.pending.size >= this.total;\n      if (!this.waitSince) this.waitSince = performance.now();\n      const waited = (performance.now() - this.waitSince) / 1000;\n      if (this.readyDur() < need && !all && waited < 3) { this.onstate(\"buffering\"); clearTimeout(this.timer); this.timer = setTimeout(() => this.drain(), 120); return; }\n      if (isRe && this.srcs.size === 0 && lead < 0) { this.underruns++; this.hold = Math.min(4, this.hold + 0.7); }\n      this.waitSince = 0;\n      this.nextTime = Math.max(now + 0.03, this.nextTime);\n    }\n    while (this.pending.has(this.expect)) { const c = this.pending.get(this.expect); this.pending.delete(this.expect); this.expect++; this.sched(c); }\n  }\n  sched(c) {\n    const buf = this.ctx.createBuffer(1, c.f32.length, c.sr); buf.copyToChannel(c.f32, 0);\n    const src = this.ctx.createBufferSource(); src.buffer = buf; src.connect(this.gain);\n    const at = Math.max(this.nextTime, this.ctx.currentTime + 0.02);\n    src.start(at); this.nextTime = at + buf.duration; this.srcs.add(src);\n    src.onended = () => { this.srcs.delete(src); this.check(); };\n    this.onstate(\"playing\");\n    if (!this.firstDone) { this.firstDone = true; this.onfirst(performance.now(), at - this.ctx.currentTime); }\n  }\n  check() {\n    if (this.total !== null && this.expect >= this.total && this.srcs.size === 0) { this.onstate(\"idle\"); if (this.underruns === 0) this.hold = Math.max(0, this.hold - 0.15); }\n  }\n}\nconst player = new GaplessPlayer();\n\n/* ---------------- 状态轮询 ---------------- */\nlet STATUS = null;\nasync function pollStatus() {\n  try {\n    const s = await (await fetch(\"/api/status\")).json(); STATUS = s;\n    const w = s.workers, st = (n) => (w[n] ? w[n].state : \"none\");\n    const ttsStates = Object.keys(w).filter((k) => k.startsWith(\"tts\")).map(st);\n    const ready = ttsStates.filter((x) => x === \"ready\").length;\n    $(\"d-tts\").className = \"dot \" + (ready === ttsStates.length ? \"ok\" : ttsStates.includes(\"error\") ? \"err\" : \"load\");\n    $(\"t-tts\").textContent = ready + \"/\" + ttsStates.length + \" 卡\" + (s.mock ? \"(模拟)\" : \"\");\n    $(\"d-llm\").className = \"dot \" + (st(\"llm\") === \"ready\" ? \"ok\" : st(\"llm\") === \"error\" ? \"err\" : \"load\");\n    $(\"t-llm\").textContent = st(\"llm\") === \"ready\" ? \"就绪\" : st(\"llm\") === \"error\" ? \"失败\" : \"加载中\";\n    [0, 1].forEach((i) => {\n      const g = (s.gpus || []).find((x) => x.index === i), el = $(\"g\" + i);\n      if (g) { el.querySelector(\"i\").style.width = Math.round((g.mem_used / g.mem_total) * 100) + \"%\"; el.querySelector(\"span\").textContent = (g.mem_used / 1024).toFixed(1) + \"G \" + g.util + \"%\"; }\n      else if (s.mock) { el.querySelector(\"span\").textContent = \"mock\"; }\n    });\n    const v = s.voice;\n    $(\"vstate\").textContent = v ? \"已训练\" + (v.similarity != null ? \" · \" + (v.similarity * 100).toFixed(1) + \"%\" : \"\") : \"未训练\";\n    const errs = Object.entries(w).filter(([, x]) => x.state === \"error\");\n    if (errs.length && !pollStatus.warned) { pollStatus.warned = 1; toast(\"模型加载失败: \" + errs[0][0] + \",请看 Kaggle 输出日志\", 6000); }\n  } catch (e) { /* 服务重启中 */ }\n}\nsetInterval(pollStatus, 2000); pollStatus();\n\n/* ---------------- 录音(克隆参考) ---------------- */\nlet refBlob = null, recorder = null, recStream = null, recStart = 0, recTimer = null, recAC = null, recAn = null, waveRAF = 0;\nconst wave = $(\"wave\"), wctx = wave.getContext(\"2d\");\nfunction fitCanvas(c) { const r = c.getBoundingClientRect(); c.width = Math.max(10, r.width * devicePixelRatio); c.height = Math.max(10, r.height * devicePixelRatio); }\nfunction drawWave() {\n  fitCanvas(wave); const W = wave.width, H = wave.height; wctx.clearRect(0, 0, W, H);\n  if (recAn) {\n    const d = new Uint8Array(recAn.fftSize); recAn.getByteTimeDomainData(d);\n    wctx.lineWidth = 2 * devicePixelRatio; const g = wctx.createLinearGradient(0, 0, W, 0); g.addColorStop(0, \"#7c5cff\"); g.addColorStop(1, \"#22d3ee\");\n    wctx.strokeStyle = g; wctx.beginPath();\n    for (let i = 0; i < d.length; i++) { const x = (i / (d.length - 1)) * W, y = (d[i] / 255) * H; i ? wctx.lineTo(x, y) : wctx.moveTo(x, y); }\n    wctx.stroke();\n  } else { wctx.fillStyle = \"rgba(255,255,255,.18)\"; wctx.fillRect(0, H / 2 - 1, W, 2); }\n  waveRAF = requestAnimationFrame(drawWave);\n}\ndrawWave();\nfunction pickMime() { const c = [\"audio/webm;codecs=opus\", \"audio/webm\", \"audio/mp4\", \"audio/ogg;codecs=opus\"]; return c.find((m) => window.MediaRecorder && MediaRecorder.isTypeSupported(m)) || \"\"; }\nasync function startRec() {\n  player.stop(); send({ type: \"stop\" });\n  try { recStream = await navigator.mediaDevices.getUserMedia({ audio: { channelCount: 1, echoCancellation: false, noiseSuppression: true, autoGainControl: false } }); }\n  catch (e) { toast(\"无法访问麦克风:请允许权限(需要 HTTPS 页面)\", 5000); return; }\n  const chunks = []; const mime = pickMime();\n  recorder = new MediaRecorder(recStream, mime ? { mimeType: mime } : undefined);\n  recorder.ondataavailable = (e) => e.data.size && chunks.push(e.data);\n  recorder.onstop = () => {\n    recStream.getTracks().forEach((t) => t.stop()); recAn = null; recAC && recAC.close(); recAC = null;\n    setRef(new Blob(chunks, { type: recorder.mimeType || \"audio/webm\" }), (performance.now() - recStart) / 1000);\n  };\n  recAC = new AudioContext(); recAn = recAC.createAnalyser(); recAn.fftSize = 1024; recAC.createMediaStreamSource(recStream).connect(recAn);\n  recorder.start(250); recStart = performance.now(); $(\"rec\").classList.add(\"on\"); $(\"rec\").textContent = \"⏹\";\n  recTimer = setInterval(() => { const s = (performance.now() - recStart) / 1000; $(\"rectime\").textContent = fmtT(s); if (s >= 30) stopRec(); }, 200);\n}\nfunction stopRec() { if (recorder && recorder.state !== \"inactive\") recorder.stop(); clearInterval(recTimer); $(\"rec\").classList.remove(\"on\"); $(\"rec\").textContent = \"🎤\"; }\n$(\"rec\").onclick = () => (recorder && recorder.state === \"recording\" ? stopRec() : startRec());\nfunction setRef(blob, secs) {\n  refBlob = blob; const p = $(\"preview\"); p.src = URL.createObjectURL(blob); p.style.display = \"block\";\n  $(\"train\").disabled = false; if (secs) $(\"rectime\").textContent = fmtT(secs);\n  if (secs && secs < 5) toast(\"录音偏短(\" + secs.toFixed(1) + \"s),建议 8~20 秒以获得更像的声音\", 4000);\n}\n$(\"upload\").onclick = () => $(\"file\").click();\n$(\"file\").onchange = (e) => { const f = e.target.files[0]; if (f) { setRef(f); toast(\"已载入: \" + f.name); } e.target.value = \"\"; };\n$(\"clear\").onclick = () => { refBlob = null; $(\"preview\").style.display = \"none\"; $(\"train\").disabled = true; $(\"rectime\").textContent = \"00:00\"; };\n\n/* ---------------- 训练 ---------------- */\nlet jobTimer = null;\n$(\"train\").onclick = async () => {\n  if (!refBlob) return;\n  const fd = new FormData(); fd.append(\"file\", refBlob, \"ref.webm\"); fd.append(\"text\", $(\"reftext\").value);\n  $(\"train\").disabled = true; $(\"result\").style.display = \"none\"; $(\"warns\").textContent = \"\";\n  const r = await fetch(\"/api/voice/train\", { method: \"POST\", body: fd });\n  if (!r.ok) { const j = await r.json().catch(() => ({})); toast(\"启动训练失败: \" + (j.detail || r.status), 5000); $(\"train\").disabled = false; return; }\n  clearInterval(jobTimer); jobTimer = setInterval(pollJob, 600); pollJob();\n};\nasync function pollJob() {\n  try {\n    const j = await (await fetch(\"/api/voice/job\")).json();\n    if (j.state === \"idle\") return;\n    $(\"pall\").style.width = (j.progress || 0) + \"%\";\n    $(\"gl\").innerHTML = (j.gpus || []).map((g) => `<b style=\"color:#cfd6ff\">GPU${g.gpu}</b><div class=\"prog\"><i style=\"width:${g.progress}%\"></i></div><span class=\"m\">${g.msg}</span>`).join(\"\")\n      + `<span class=\"m\" style=\"color:#cfd6ff\">${j.stage || \"\"}</span>`;\n    $(\"warns\").textContent = (j.warnings || []).join(\" · \");\n    if (j.state === \"done\" || j.state === \"error\") {\n      clearInterval(jobTimer); $(\"train\").disabled = !refBlob;\n      if (j.state === \"done\") {\n        const sim = j.similarity; $(\"result\").style.display = \"flex\";\n        $(\"ring\").style.setProperty(\"--p\", sim != null ? Math.min(100, sim * 100) : 0);\n        $(\"ringv\").textContent = sim != null ? (sim * 100).toFixed(1) + \"%\" : \"—\";\n        $(\"rmode\").textContent = \"训练完成 · 模式 \" + (j.mode === \"icl\" ? \"ICL 上下文克隆\" : \"x-vector 声纹克隆\");\n        $(\"rinfo\").textContent = \"说话人嵌入相似度 · 文本:\" + (j.ref_text || \"\").slice(0, 28);\n        toast(\"声音训练完成,可以开始对话了\");\n        if (!$(\"reftext\").value) $(\"reftext\").value = j.ref_text || \"\";\n        pollStatus();\n      } else { toast(\"训练失败: \" + j.error, 6000); }\n    }\n  } catch (e) {}\n}\n\n/* ---------------- WebSocket / 对话 ---------------- */\nlet lastMsgAt = 0, gotStart = false, ws = null, wsReady = false, tSend = 0, curBubble = null, autoPlay = true, longMode = false, fillerOn = true;\nfunction setConn(ok) { const d = $(\"d-conn\"); if (d) { d.className = \"dot \" + (ok ? \"ok\" : \"err\"); $(\"t-conn\").textContent = ok ? \"已连接\" : \"重连中\"; } }\nfunction connectWS() {\n  ws = new WebSocket((location.protocol === \"https:\" ? \"wss://\" : \"ws://\") + location.host + \"/ws\"); ws.binaryType = \"arraybuffer\";\n  ws.onopen = () => { wsReady = true; setConn(true); };\n  ws.onclose = () => { wsReady = false; setConn(false); if (curBubble) { addMsg(\"e\", \"⚠ 与服务器的连接中断,正在自动重连…(如果持续失败,请确认 Kaggle 单元格仍在运行)\"); endBubble(); } setTimeout(connectWS, 1200); };\n  ws.onmessage = (ev) => {\n    lastMsgAt = performance.now();\n    if (typeof ev.data !== \"string\") {\n      const dv = new DataView(ev.data), turn = dv.getUint32(0, true), idx = dv.getUint32(4, true), sr = dv.getUint32(8, true);\n      if (!autoPlay) return;\n      const i16 = new Int16Array(ev.data, 16, (ev.data.byteLength - 16) >> 1), f = new Float32Array(i16.length);\n      for (let i = 0; i < i16.length; i++) f[i] = i16[i] / 32768;\n      player.push(turn, idx, sr, f); return;\n    }\n    const m = JSON.parse(ev.data);\n    if (m.type === \"start\") { gotStart = true; player.ensure(); player.newTurn(m.turn); player.fillerFirst = !!m.filler; }\n    else if (m.type === \"text\") { if (curBubble) { curBubble.textContent += m.delta; scrollDown(); } }\n    else if (m.type === \"notice\") addMsg(\"s\", m.text);\n    else if (m.type === \"warn\") toast(m.text, 4000);\n    else if (m.type === \"error\") { endBubble(); addMsg(\"e\", \"⚠ \" + m.text); }\n    else if (m.type === \"done\") {\n      endBubble(); player.finish(m.stats.chunks);\n      const g = m.stats.gpu_chunks || {}; const gs = Object.keys(g).sort().map((k) => k.toUpperCase() + \"×\" + g[k]).join(\" \");\n      $(\"ttfa\").title = \"服务端首声 \" + m.stats.ttfa_ms + \"ms · LLM首字 \" + m.stats.llm_first_ms + \"ms · \" + gs;\n      if (m.stats.chunks) addMsg(\"s\", `音频 ${m.stats.audio_s}s · 首声 ${((m.stats.ttfa_ms || 0) / 1000).toFixed(2)}s · 正文首声 ${((m.stats.body_ttfa_ms || 0) / 1000).toFixed(2)}s · ${gs}${player.underruns ? \" · 自适应缓冲已调整\" : \"\"}`);\n    } else if (m.type === \"stopped\") { player.stop(); endBubble(); }\n  };\n}\nconnectWS(); setInterval(() => wsReady && ws.send('{\"type\":\"ping\"}'), 20000);\n/* 看门狗:发送后如果服务端长时间没有任何输出,必须明确告诉用户,而不是一直转圈 */\nsetInterval(() => {\n  if (!curBubble) return;\n  const idle = (performance.now() - lastMsgAt) / 1000;\n  if ((!gotStart && idle > 12) || idle > 50) {\n    addMsg(\"e\", gotStart ? \"⚠ 服务端 50 秒没有任何输出。请点「停止」后重试;并查看 Kaggle 输出框里的 [turn]/[llm] 日志。\" : \"⚠ 服务端 12 秒没有响应。可能服务正在重启或网络断开,请稍后重试。\");\n    endBubble();\n  }\n}, 2000);\nfunction send(o) { if (wsReady) ws.send(JSON.stringify(o)); }\nplayer.onstate = (s) => { $(\"pstate\").textContent = { idle: \"待机\", playing: \"● 正在朗读\", buffering: \"缓冲中…\" }[s] || s; $(\"pstate\").style.color = s === \"playing\" ? \"var(--ok)\" : \"var(--mut)\"; };\nplayer.onfirst = (now, lead) => { const ms = now - tSend + lead * 1000; $(\"ttfa\").textContent = (ms / 1000).toFixed(2) + \"s\"; $(\"ttfa\").style.color = ms < 3000 ? \"var(--ok)\" : \"var(--warn)\"; };\nfunction scrollDown() { const m = $(\"msgs\"); m.scrollTop = m.scrollHeight; }\nfunction addMsg(cls, text) {\n  const m = $(\"msgs\"); const e = m.querySelector(\".empty\"); if (e) e.remove();\n  const d = document.createElement(\"div\"); d.className = \"msg \" + cls; d.textContent = text; m.appendChild(d); scrollDown(); return d;\n}\nfunction endBubble() { if (curBubble) { curBubble.classList.remove(\"live\"); curBubble = null; } }\nfunction sendChat(text) {\n  text = (text || \"\").trim(); if (!text) return false;\n  if (!wsReady) { toast(\"正在连接服务器,请稍候再发送…\", 3000); return false; }\n  player.ensure(); player.stop(); endBubble();\n  addMsg(\"u\", text); curBubble = addMsg(\"a live\", \"\"); tSend = performance.now(); lastMsgAt = tSend; gotStart = false;\n  send({ type: \"chat\", text, opts: { long: longMode, breath: $(\"breath\").value / 100, filler: fillerOn } });\n  return true;\n}\n$(\"send\").onclick = () => { const v = $(\"input\").value; if (sendChat(v)) $(\"input\").value = \"\"; };\n$(\"input\").addEventListener(\"keydown\", (e) => { if (e.key === \"Enter\" && !e.isComposing) $(\"send\").click(); });\ndocument.addEventListener(\"keydown\", (e) => { if (e.key === \"Escape\") $(\"stop\").click(); });\n$(\"stop\").onclick = () => { send({ type: \"stop\" }); player.stop(); endBubble(); };\n$(\"reset\").onclick = () => { send({ type: \"reset\" }); player.stop(); $(\"msgs\").innerHTML = \"\"; addMsg(\"s\", \"已开始新对话\"); };\nconst tgl = (id, cb) => { const e = $(id); e.onclick = (ev) => { if (ev.target.tagName === \"INPUT\") return; e.classList.toggle(\"on\"); cb(e.classList.contains(\"on\")); }; };\ntgl(\"tgAuto\", (v) => { autoPlay = v; if (!v) player.stop(); }); tgl(\"tgLong\", (v) => (longMode = v)); tgl(\"tgSmooth\", (v) => (player.floor = v ? 1.2 : 0)); tgl(\"tgFiller\", (v) => (fillerOn = v));\n\n/* ---------------- 语音输入(自动断句) ---------------- */\nlet micRec = null, micStream = null, micAC = null, micRAF = 0;\n$(\"mic\").onclick = async () => {\n  if (micRec && micRec.state === \"recording\") { micRec.stop(); return; }\n  player.stop(); send({ type: \"stop\" }); player.ensure();\n  try { micStream = await navigator.mediaDevices.getUserMedia({ audio: { channelCount: 1, echoCancellation: true, noiseSuppression: true } }); }\n  catch (e) { toast(\"无法访问麦克风:请允许权限\", 4000); return; }\n  const chunks = [], mime = pickMime(); micRec = new MediaRecorder(micStream, mime ? { mimeType: mime } : undefined);\n  micRec.ondataavailable = (e) => e.data.size && chunks.push(e.data);\n  micAC = new AudioContext(); const an = micAC.createAnalyser(); an.fftSize = 1024; micAC.createMediaStreamSource(micStream).connect(an);\n  const buf = new Float32Array(an.fftSize); let spoke = false, silentSince = 0; const t0 = performance.now();\n  const loop = () => {\n    if (!micRec || micRec.state !== \"recording\") return;\n    an.getFloatTimeDomainData(buf); let s = 0; for (const v of buf) s += v * v; const rms = Math.sqrt(s / buf.length), now = performance.now();\n    if (rms > 0.02) { spoke = true; silentSince = 0; } else if (spoke && !silentSince) silentSince = now;\n    if ((spoke && silentSince && now - silentSince > 1300) || now - t0 > 45000 || (!spoke && now - t0 > 9000)) { micRec.stop(); return; }\n    micRAF = requestAnimationFrame(loop);\n  };\n  micRec.onstop = async () => {\n    cancelAnimationFrame(micRAF); micStream.getTracks().forEach((t) => t.stop()); micAC.close(); $(\"mic\").classList.remove(\"on\");\n    if (!spoke) { toast(\"没有听到声音\"); return; }\n    $(\"input\").placeholder = \"识别中…\";\n    try {\n      const r = await fetch(\"/api/asr\", { method: \"POST\", headers: { \"Content-Type\": \"application/octet-stream\" }, body: new Blob(chunks) });\n      const j = await r.json(); if (j.error) throw new Error(j.error);\n      if (j.text) sendChat(j.text); else toast(\"没有识别到内容\");\n    } catch (e) { toast(\"识别失败: \" + e.message, 4000); }\n    $(\"input\").placeholder = \"输入消息,回车发送 …\";\n  };\n  micRec.start(250); $(\"mic\").classList.add(\"on\"); loop();\n};\n\n/* ---------------- 播放可视化 ---------------- */\nconst viz = $(\"viz\"), vctx = viz.getContext(\"2d\");\n(function drawViz() {\n  const W = viz.width, H = viz.height; vctx.clearRect(0, 0, W, H);\n  if (player.an) {\n    const d = new Uint8Array(player.an.frequencyBinCount); player.an.getByteFrequencyData(d);\n    const n = 22, bw = W / n; const g = vctx.createLinearGradient(0, 0, W, 0); g.addColorStop(0, \"#7c5cff\"); g.addColorStop(1, \"#22d3ee\"); vctx.fillStyle = g;\n    for (let i = 0; i < n; i++) { const v = d[Math.floor((i / n) * 40)] / 255, h = Math.max(3, v * H); vctx.fillRect(i * bw + 2, (H - h) / 2, bw - 4, h); }\n  }\n  requestAnimationFrame(drawViz);\n})();\n\n/* ---------------- 入口 & 标签页 ---------------- */\n$(\"enter\").onclick = () => { player.ensure(); $(\"gate\").style.display = \"none\"; };\ndocument.querySelectorAll(\".tabs button\").forEach((b) => (b.onclick = () => { $(\"main\").dataset.tab = b.dataset.t; document.querySelectorAll(\".tabs button\").forEach((x) => x.classList.toggle(\"on\", x === b)); }));\ndocument.addEventListener(\"pointerdown\", () => player.ctx && player.ctx.state !== \"running\" && player.ctx.resume(), { passive: true });\n</script>\n</body>\n</html>\n","kaggle/run.py":"\"\"\"Kaggle 一键启动器 (Accelerator 请选 GPU T4 x2,Internet 打开)。\n\n流程: 检查双卡 → 装依赖 → 并行预下载模型 → 启动服务 → 建立公网隧道 → 在输出框打印可点击网址。\n用法(Kaggle 单元格):  !python /kaggle/working/clone-system/kaggle/run.py\n\"\"\"\nimport os\nimport re\nimport shutil\nimport subprocess\nimport sys\nimport threading\nimport time\nimport urllib.request\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parent.parent\nPORT = int(os.environ.get(\"PORT\", \"7860\"))\nMARK = Path(\"/tmp/.clone_deps_ok_v3\")\n\n\ndef log(*a):\n    print(\"[kaggle-run]\", *a, flush=True)\n\n\ndef sh(cmd, check=True):\n    log(\"$\", cmd)\n    return subprocess.run(cmd, shell=True, check=check)\n\n\ndef load_secrets():\n    try:\n        from kaggle_secrets import UserSecretsClient\n\n        c = UserSecretsClient()\n        for name in (\"HF_TOKEN\", \"NGROK_TOKEN\", \"NGROK_AUTHTOKEN\"):\n            try:\n                os.environ[name] = c.get_secret(name)\n                log(\"已读取 Kaggle Secret:\", name)\n            except Exception:  # noqa: BLE001\n                pass\n    except Exception:  # noqa: BLE001\n        pass\n\n\ndef check_gpus():\n    try:\n        out = subprocess.run([\"nvidia-smi\", \"-L\"], capture_output=True, text=True).stdout.strip().splitlines()\n    except FileNotFoundError:\n        out = []\n    log(\"检测到 GPU 数量:\", len(out))\n    for l in out:\n        log(\"  \", l)\n    if len(out) < 2:\n        log(\"⚠ 少于 2 张 GPU!请在 Settings → Accelerator 选择 'GPU T4 x2'。将降级为单卡运行(速度会变慢)。\")\n    return len(out)\n\n\ndef _torch_constraints():\n    \"\"\"锁定 Kaggle 自带的 torch 系列版本,防止 pip 升级 torch 后与 GPU 驱动不匹配。\"\"\"\n    out = subprocess.run([sys.executable, \"-m\", \"pip\", \"freeze\"], capture_output=True, text=True).stdout.splitlines()\n    keep = [l for l in out if re.match(r\"^(torch|torchvision|torchaudio)==\", l, re.I)]\n    f = Path(\"/tmp/torch_constraints.txt\")\n    f.write_text(\"\\n\".join(keep) + \"\\n\")\n    log(\"锁定:\", \", \".join(keep) or \"(无)\")\n    return f\n\n\ndef install_deps():\n    base = \"fastapi 'uvicorn[standard]' python-multipart soundfile scipy noisereduce accelerate huggingface_hub\"\n    if MARK.exists():\n        log(\"依赖已安装,跳过\")\n    else:\n        c = _torch_constraints()\n        # 首选 faster-qwen3-tts: CUDA Graph + 流式输出 (T4 上 RTF 约 2x 提升,首块音频约 1 秒)\n        r = sh(\"pip install -q -c %s faster-qwen3-tts %s\" % (c, base), check=False)\n        if r.returncode != 0:\n            log(\"⚠ faster-qwen3-tts 安装失败,回退官方 qwen-tts(整句合成,首声会慢)\")\n            sh(\"pip install -q -c %s qwen-tts %s\" % (c, base))\n        MARK.write_text(\"ok\")\n    chk = subprocess.run([sys.executable, \"-c\", \"import faster_qwen3_tts\"], capture_output=True, text=True)\n    if chk.returncode == 0:\n        log(\"✓ faster-qwen3-tts 可用(CUDA Graph 流式)\")\n    else:\n        log(\"faster-qwen3-tts 不可用,将使用官方 qwen-tts:\", (chk.stderr.strip().splitlines() or [\"?\"])[-1])\n    if not shutil.which(\"ffmpeg\"):\n        log(\"未找到 ffmpeg,尝试安装(浏览器录音 webm 需要它)\")\n        sh(\"apt-get install -y -qq ffmpeg > /dev/null 2>&1\", check=False)\n    if not shutil.which(\"ffmpeg\"):\n        sh(\"pip install -q imageio-ffmpeg\", check=False)\n        try:\n            import imageio_ffmpeg\n\n            d = Path(\"/tmp/ffbin\")\n            d.mkdir(exist_ok=True)\n            link = d / \"ffmpeg\"\n            if not link.exists():\n                link.symlink_to(imageio_ffmpeg.get_ffmpeg_exe())\n            os.environ[\"PATH\"] = str(d) + os.pathsep + os.environ[\"PATH\"]\n        except Exception as e:  # noqa: BLE001\n            log(\"ffmpeg 安装失败:\", e)\n    log(\"ffmpeg:\", shutil.which(\"ffmpeg\"))\n\n\ndef predownload():\n    sys.path.insert(0, str(ROOT))\n    from concurrent.futures import ThreadPoolExecutor\n\n    from huggingface_hub import snapshot_download\n\n    from server import config\n\n    repos = [config.TTS_MODEL, config.LLM_MODEL, config.ASR_MODEL, config.SV_MODEL]\n\n    def dl(r):\n        t = time.time()\n        try:\n            snapshot_download(r, token=os.environ.get(\"HF_TOKEN\") or None)\n            log(\"✓ 模型就绪 %s (%.0fs)\" % (r, time.time() - t))\n        except Exception as e:  # noqa: BLE001\n            log(\"✗ 下载失败 %s: %s\" % (r, e))\n\n    with ThreadPoolExecutor(4) as ex:\n        list(ex.map(dl, repos))\n\n\ndef pump(proc, prefix):\n    for line in iter(proc.stdout.readline, \"\"):\n        print(prefix + line.rstrip(), flush=True)\n\n\ndef start_server():\n    env = dict(os.environ, PYTHONUNBUFFERED=\"1\", PORT=str(PORT))\n    p = subprocess.Popen(\n        [sys.executable, \"-m\", \"uvicorn\", \"server.app:app\", \"--host\", \"0.0.0.0\", \"--port\", str(PORT), \"--ws-ping-interval\", \"20\"],\n        cwd=ROOT, env=env, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True,\n    )\n    threading.Thread(target=pump, args=(p, \"[server] \"), daemon=True).start()\n    for _ in range(120):\n        try:\n            urllib.request.urlopen(\"http://127.0.0.1:%d/api/health\" % PORT, timeout=2)\n            log(\"服务已启动 (端口 %d)\" % PORT)\n            return p\n        except Exception:  # noqa: BLE001\n            time.sleep(1)\n    raise RuntimeError(\"服务启动超时\")\n\n\ndef start_cloudflared():\n    exe = Path(\"/tmp/cloudflared\")\n    if not exe.exists():\n        url = \"https://github.com/cloudflare/cloudflared/releases/latest/download/cloudflared-linux-amd64\"\n        log(\"下载 cloudflared …\")\n        urllib.request.urlretrieve(url, exe)\n        exe.chmod(0o755)\n    p = subprocess.Popen(\n        [str(exe), \"tunnel\", \"--url\", \"http://127.0.0.1:%d\" % PORT, \"--no-autoupdate\"],\n        stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True,\n    )\n    found = {}\n\n    def rd():\n        for line in iter(p.stdout.readline, \"\"):\n            m = re.search(r\"https://[a-z0-9-]+\\.trycloudflare\\.com\", line)\n            if m and \"url\" not in found:\n                found[\"url\"] = m.group(0)\n\n    threading.Thread(target=rd, daemon=True).start()\n    for _ in range(60):\n        if \"url\" in found:\n            return found[\"url\"]\n        time.sleep(1)\n    return None\n\n\ndef start_ngrok():\n    tok = os.environ.get(\"NGROK_TOKEN\") or os.environ.get(\"NGROK_AUTHTOKEN\")\n    if not tok:\n        return None\n    sh(\"pip install -q pyngrok\", check=False)\n    from pyngrok import ngrok\n\n    ngrok.set_auth_token(tok)\n    return ngrok.connect(PORT, \"http\").public_url\n\n\ndef banner(url):\n    line = \"=\" * 74\n    print(\"\\n\" + line)\n    print(\"  ✅ 克隆语音系统已就绪,请打开下面的网址(粘贴到「浏览器模拟器」地址栏即可):\")\n    print(\"\\n      \" + url + \"\\n\")\n    print(line + \"\\n\", flush=True)\n    try:\n        from IPython.display import HTML, display\n\n        display(HTML('<h2>🎙 <a href=\"%s\" target=\"_blank\" style=\"color:#7c5cff\">打开克隆语音系统</a></h2><p>%s</p>' % (url, url)))\n    except Exception:  # noqa: BLE001\n        pass\n\n\ndef main():\n    log(\"工作目录:\", ROOT)\n    load_secrets()\n    check_gpus()\n    install_deps()\n    if os.environ.get(\"CLONE_MOCK\") != \"1\":\n        predownload()\n    server = start_server()\n    url = None\n    for fn in (start_cloudflared, start_ngrok):\n        try:\n            url = fn()\n        except Exception as e:  # noqa: BLE001\n            log(\"隧道失败\", fn.__name__, e)\n        if url:\n            break\n    if url:\n        banner(url)\n    else:\n        log(\"⚠ 未能建立公网隧道。可在 Kaggle Secrets 添加 NGROK_TOKEN 后重试。\")\n    try:\n        server.wait()\n    except KeyboardInterrupt:\n        server.terminate()\n\n\nif __name__ == \"__main__\":\n    main()\n","tests/e2e_mock.py":"\"\"\"端到端自检(Mock 模式,无需 GPU):  python tests/e2e_mock.py\n验证: 启动 → 训练(双卡) → 流式对话 → 音频顺序/无缺口 → 停止 → ASR → 错误必回显 → 前端页面(无摄像头)。\"\"\"\nimport asyncio\nimport io\nimport json\nimport os\nimport struct\nimport subprocess\nimport sys\nimport time\nfrom pathlib import Path\n\nimport httpx\nimport numpy as np\nimport soundfile as sf\nimport websockets\n\nROOT = Path(__file__).resolve().parent.parent\nPORT = int(os.environ.get(\"TEST_PORT\", \"7861\"))\nBASE = \"http://127.0.0.1:%d\" % PORT\nfails = []\n\n\ndef check(name, cond, extra=\"\"):\n    print((\"PASS \" if cond else \"FAIL \") + name + (\" -> \" + str(extra) if extra else \"\"))\n    if not cond:\n        fails.append(name)\n\n\ndef make_ref():\n    sr = 24000\n    t = np.arange(sr * 8) / sr\n    x = 0.3 * np.sin(2 * np.pi * 180 * t) * (0.6 + 0.4 * np.sin(2 * np.pi * 2 * t))\n    x += 0.003 * np.random.randn(len(t))\n    buf = io.BytesIO()\n    sf.write(buf, x.astype(np.float32), sr, format=\"WAV\")\n    return buf.getvalue()\n\n\nasync def chat(opts_text, ws_url, kind=\"chat\", extra=None):\n    frames, texts, done, t0 = [], [], None, time.time()\n    first = None\n    async with websockets.connect(ws_url, max_size=None) as ws:\n        await ws.send(json.dumps({\"type\": kind, \"text\": opts_text, \"opts\": dict({\"breath\": 0.4}, **(extra or {}))}))\n        while True:\n            m = await asyncio.wait_for(ws.recv(), 30)\n            if isinstance(m, bytes):\n                turn, idx, sr, _ = struct.unpack(\"<IIII\", m[:16])\n                if first is None:\n                    first = time.time() - t0\n                frames.append((turn, idx, sr, len(m) - 16))\n            else:\n                j = json.loads(m)\n                if j[\"type\"] == \"text\":\n                    texts.append(j[\"delta\"])\n                if j[\"type\"] == \"done\":\n                    done = j\n                    break\n                if j[\"type\"] == \"error\":\n                    done = j\n                    break\n    return frames, \"\".join(texts), done, first\n\n\nasync def stop_test(ws_url):\n    async with websockets.connect(ws_url, max_size=None) as ws:\n        await ws.send(json.dumps({\"type\": \"chat\", \"text\": \"请讲一个很长很长的故事\"}))\n        got = 0\n        t0 = time.time()\n        while time.time() - t0 < 1.2:\n            try:\n                m = await asyncio.wait_for(ws.recv(), 0.5)\n                got += 1\n            except asyncio.TimeoutError:\n                pass\n        await ws.send(json.dumps({\"type\": \"stop\"}))\n        stopped = False\n        t1 = time.time()\n        while time.time() - t1 < 3:\n            try:\n                m = await asyncio.wait_for(ws.recv(), 0.5)\n                if isinstance(m, str) and json.loads(m)[\"type\"] == \"stopped\":\n                    stopped = True\n                    break\n            except asyncio.TimeoutError:\n                pass\n        return got, stopped\n\n\ndef test_chunker():\n    sys.path.insert(0, str(ROOT))\n    from server.text_chunker import SentenceChunker, clean_for_tts, detect_language\n\n    c = SentenceChunker()\n    out = []\n    for ch in \"好的,我来帮你。今天天气很好,适合出去走走,你觉得呢?最后一句没有标点\":\n        out += c.feed(ch)\n    out += c.flush()\n    check(\"chunker first piece short\", len(out[0]) <= 14 and len(out) >= 3, out)\n    check(\"chunker lossless\", \"\".join(out) == \"好的,我来帮你。今天天气很好,适合出去走走,你觉得呢?最后一句没有标点\", out)\n    check(\"clean markdown/emoji\", clean_for_tts(\"**你好** 😀 [链接](http://a.b) `x`\") == \"你好 链接 x\", clean_for_tts(\"**你好** 😀 [链接](http://a.b) `x`\"))\n    check(\"detect lang\", detect_language(\"你好世界\") == \"Chinese\" and detect_language(\"hello world\") == \"English\")\n\n\ndef main():\n    test_chunker()\n    env = dict(os.environ, CLONE_MOCK=\"1\", CLONE_DATA=str(ROOT / \"data_test\"))\n    p = subprocess.Popen([sys.executable, \"-m\", \"uvicorn\", \"server.app:app\", \"--port\", str(PORT)], cwd=ROOT, env=env)\n    try:\n        c = httpx.Client(base_url=BASE, timeout=30)\n        for _ in range(60):\n            try:\n                if c.get(\"/api/health\").status_code == 200:\n                    break\n            except Exception:\n                time.sleep(0.5)\n        else:\n            check(\"server up\", False)\n            return\n        check(\"server up\", True)\n        page = c.get(\"/\")\n        check(\"index.html served\", page.status_code == 200 and \"Voice Clone Studio\" in page.text)\n        check(\"iframe allowed\", \"frame-ancestors *\" in page.headers.get(\"content-security-policy\", \"\"))\n        time.sleep(2)\n        st = c.get(\"/api/status\").json()\n        check(\"2 tts workers + llm + aux ready\", all(w[\"state\"] == \"ready\" for w in st[\"workers\"].values()) and len([k for k in st[\"workers\"] if k.startswith(\"tts\")]) == 2, {k: v[\"state\"] for k, v in st[\"workers\"].items()})\n\n        r = c.post(\"/api/voice/train\", files={\"file\": (\"ref.wav\", make_ref(), \"audio/wav\")}, data={\"text\": \"\"})\n        check(\"train accepted\", r.status_code == 200, r.text)\n        job = {}\n        for _ in range(60):\n            job = c.get(\"/api/voice/job\").json()\n            if job.get(\"state\") in (\"done\", \"error\"):\n                break\n            time.sleep(0.5)\n        check(\"train done\", job.get(\"state\") == \"done\", job.get(\"error\") or job.get(\"log\", [])[-2:])\n        check(\"both gpus participated\", all(g[\"progress\"] == 100 for g in job.get(\"gpus\", [])) and len(job.get(\"gpus\", [])) == 2, job.get(\"gpus\"))\n        check(\"similarity reported\", job.get(\"similarity\") is not None, job.get(\"similarity\"))\n        check(\"ref.wav downloadable\", c.get(\"/api/voice/ref.wav\").status_code == 200)\n\n        ws_url = \"ws://127.0.0.1:%d/ws\" % PORT\n        frames, text, done, first = asyncio.run(chat(\"你好,请介绍一下你自己\", ws_url))\n        check(\"chat done\", done and done[\"type\"] == \"done\", done)\n        idxs = [f[1] for f in frames]\n        check(\"audio idx sequential\", idxs == list(range(len(idxs))) and len(idxs) >= 3, idxs)\n        check(\"both GPUs used in chat\", len(done[\"stats\"][\"gpu_chunks\"]) == 2, done[\"stats\"][\"gpu_chunks\"])\n        check(\"first audio < 3s\", first is not None and first < 3, first)\n        check(\"text streamed\", len(text) > 40, len(text))\n        check(\"filler played first (0-latency voice)\", done[\"stats\"].get(\"filler\") and done[\"stats\"][\"ttfa_ms\"] < done[\"stats\"][\"body_ttfa_ms\"], done[\"stats\"])\n        frames3, text3, done3, _ = asyncio.run(chat(\"你好\", ws_url, extra={\"filler\": False}))\n        check(\"filler can be disabled\", done3[\"stats\"].get(\"filler\") is None and len(frames3) >= 1, done3[\"stats\"])\n        check(\"chunk count matches\", done[\"stats\"][\"chunks\"] == len(frames), (done[\"stats\"][\"chunks\"], len(frames)))\n\n        frames2, text2, done2, _ = asyncio.run(chat(\"这是一句直接朗读的话。第二句也要读出来。\", ws_url, \"speak\"))\n        check(\"speak-only works\", done2[\"type\"] == \"done\" and len(frames2) >= 1, done2)\n\n        got, stopped = asyncio.run(stop_test(ws_url))\n        check(\"stop works\", stopped and got > 0, (got, stopped))\n\n        a = c.post(\"/api/asr\", content=make_ref(), headers={\"content-type\": \"application/octet-stream\"})\n        check(\"asr works\", a.status_code == 200 and a.json().get(\"text\"), a.text[:100])\n        check(\"camera/detect removed\", c.post(\"/api/detect\", content=b\"x\").status_code in (404, 405) and \"getUserMedia({ video\" not in page.text and \"摄像头\" not in page.text)\n        # 关键回归: LLM 出错时界面必须收到明确的 error,而不是永远转圈\n        fr4, tx4, done4, _ = asyncio.run(chat(\"__LLM_FAIL__ 你好\", ws_url))\n        check(\"LLM failure is reported (never silent)\", done4 and done4[\"type\"] == \"error\" and \"LLM\" in done4.get(\"text\", \"\"), done4)\n        fr5, tx5, done5, _ = asyncio.run(chat(\"故障之后还能正常聊天\", ws_url))\n        check(\"chat works after a failed turn\", done5 and done5[\"type\"] == \"done\", done5)\n    finally:\n        p.terminate()\n        try:\n            p.wait(5)\n        except Exception:\n            p.kill()\n    print(\"\\n结果:\", \"全部通过\" if not fails else \"失败 %s\" % fails)\n    sys.exit(1 if fails else 0)\n\n\nif __name__ == \"__main__\":\n    main()\n","requirements.txt":"faster-qwen3-tts\nfastapi\nuvicorn[standard]\npython-multipart\nsoundfile\nscipy\nnoisereduce\naccelerate\nhuggingface_hub\n","README.md":"# biyesheji · 克隆语音系统 (Voice Clone Studio)\n\n在 **Kaggle GPU T4 x2** 上部署的实时语音克隆 + 语音/文字对话系统(已移除摄像头/物体检测)。\n\n## 架构(双卡并行,模型常驻显存)\n\n| 进程 | GPU | 作用 |\n| --- | --- | --- |\n| `tts0` | GPU0 | Qwen3-TTS-12Hz-1.7B-Base 声音克隆(faster-qwen3-tts: CUDA Graph + 流式输出) |\n| `tts1` | GPU1 | Qwen3-TTS-12Hz-1.7B-Base 声音克隆(同上) |\n| `llm`  | GPU0 | Qwen3-4B-Instruct-2507 流式长文本对话(支持 256K 上下文,长文模式 4096 token) |\n| `aux`  | GPU1 | Whisper(语音识别) + WavLM(说话人相似度) |\n\n每个进程用 `CUDA_VISIBLE_DEVICES` 独占一张卡,互不抢 GIL,双卡真并行。服务进程不退出,模型就一直常驻显存。\n\n## 数据流\n\n- **训练**(点击「开始训练」):参考音频清洗(高通/降噪/切静音/归一化)→ Whisper 自动转写 → **双卡同时**构建声纹并预热 CUDA Graph → ICL / x-vector 两种克隆模式**分别在两张卡上同时**合成校验句 → WavLM 计算说话人相似度 → 择优 → 双卡并行缓存「语气词」。\n- **对话**:LLM 流式输出 → 首句 3~14 字即切句 → 每句分配给空闲的卡 → **每 0.33~0.67 秒音频就流式推送一块** → 带状态后处理(跨块连续高通滤波、整句固定增益、句末才淡出、软限幅)→ WebSocket → 浏览器 WebAudio 无缝排队播放(缺料时自适应加大缓冲)。\n- **首声**:克隆声音的「嗯,」「好的,」等语气词在训练时预先缓存,每轮对话开口即播(≈0 延迟),正文同时在双卡合成。\n- **不会「发了没反应」**:LLM 生成线程里的任何异常都会被捕获并回显到界面;fp16 溢出自动改用 bf16 重试;服务端 60 秒无输出会报错;前端有 12 秒/50 秒看门狗。\n\n## 文件\n\n```\nserver/        后端 (FastAPI + 多进程 GPU worker)\nweb/index.html 前端(单屏,无需滚动)\nkaggle/run.py  Kaggle 启动器(装依赖/下载模型/起服务/建公网隧道)\ntests/         Mock 端到端自检 (CLONE_MOCK=1, 不需要 GPU)\nkaggle_all_in_one.py  粘贴到 Kaggle 单元格即可运行的完整脚本(内置以上全部文件)\n```\n\n## 在 Kaggle 运行\n\n1. Notebook 右侧 Settings:Accelerator = **GPU T4 x2**,Internet = **On**。\n2. 把「复制代码」页面里的 `kaggle_all_in_one.py` 整个粘贴到一个代码单元格运行。\n3. 输出框会打印 `https://xxxx.trycloudflare.com`,粘贴到浏览器模拟器地址栏即可。\n4. 首次运行需要下载约 15GB 模型并安装依赖(约 8~15 分钟);之后同一会话内再次运行很快。\n\n## 本地自检(无 GPU)\n\n```\nCLONE_MOCK=1 python tests/e2e_mock.py\n```\n\n## 关于指标的说明(请读)\n\n- “首声 < 3 秒”:T4 上 1.7B 模型的流式首块约 1 秒,加上语气词先行,通常能在 3 秒内听到声音;界面实时显示真实测得的首声时间。\n- T4 单卡合成速度约为实时的 0.9 倍;系统用「双卡交替合成 + 自适应缓冲」保证播放不断流,但**不是**数学意义上的绝对保证。\n- “相似度”显示的是 WavLM 说话人嵌入余弦相似度,是真实测量值;99.5% 在该度量下不是一个可保证的数值,系统通过「择优模式 + 高质量参考音频」尽量提高它。参考音频越干净(安静环境、8~20 秒、情绪自然)越像。\n- Kaggle 会话有时长上限(约 12 小时/长时间无操作会断开),会话结束后模型随之卸载,重新运行单元格即可。\n",".gitignore":"__pycache__/\n*.pyc\ndata/\ndata_test/\n*.wav\n.env\n"}''')

try:
    n_gpu = len(subprocess.run(["nvidia-smi", "-L"], capture_output=True, text=True).stdout.strip().splitlines())
except FileNotFoundError:
    n_gpu = 0
print("检测到 GPU 数量:", n_gpu, "(需要 2 张: 右侧 Settings → Accelerator → GPU T4 x2)")

for rel, content in FILES.items():
    p = ROOT / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(content, encoding="utf-8")
print("已写入 %d 个文件 -> %s" % (len(FILES), ROOT))

if USE_GITHUB:
    tmp = Path("/tmp/gh_clone")
    shutil.rmtree(tmp, ignore_errors=True)
    r = subprocess.run(["git", "clone", "--depth", "1", GITHUB_REPO, str(tmp)])
    if r.returncode == 0:
        for d in ("server", "web", "kaggle"):
            if (tmp / d).exists():
                shutil.copytree(tmp / d, ROOT / d, dirs_exist_ok=True)
        print("已用 GitHub 最新代码覆盖")
    else:
        print("GitHub 拉取失败,继续使用内置代码")

proc = subprocess.Popen([sys.executable, "-u", str(ROOT / "kaggle" / "run.py")], cwd=str(ROOT),
                        stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
shown = False
try:
    for line in proc.stdout:
        print(line, end="")
        m = re.search(r"https://[a-z0-9-]+\.(?:trycloudflare\.com|ngrok[-a-z.]*)", line)
        if m and not shown:
            shown = True
            try:
                from IPython.display import HTML, display
                display(HTML('<h2>🎙 <a href="%s" target="_blank">点此打开克隆语音系统</a></h2><p>%s</p>' % (m.group(0), m.group(0))))
            except Exception:
                pass
except KeyboardInterrupt:
    proc.terminate()
